('8c60c532-de7e-53f5-acb1-17b34df44501','9aac901d-a1dd-5521-a943-89c7815b2376',1,'noun','B1','S2','W1','[ countable ]','[{"phrase":"the elements","register":null,"definition_en":"the weather , especially bad weather","translation":"آب و هوا، به خصوص آب و هوای بد","example":"sailors battling against the elements","example_translation":"ملوانان در حال نبرد با عناصر","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001184328.mp3"},{"phrase":"the elements of something","register":null,"definition_en":"the most simple things that you have to learn first about a subject","translation":"ساده ترین چیزهایی که ابتدا باید در مورد یک موضوع یاد بگیرید","example":"She doesn’t even know the basic elements of politeness.","example_translation":"او حتی عناصر اولیه ادب را نمی داند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001184340.mp3"},{"phrase":"be in your element","register":null,"definition_en":"to be in a situation that you enjoy , because you are good at it","translation":"قرار گرفتن در موقعیتی که از آن لذت می برید، زیرا در آن مهارت دارید","example":"Graham was in his element, building a fire and cooking the steaks.","example_translation":"گراهام در حال ساختن آتش و پختن استیک ها بود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001184349.mp3"},{"phrase":"be out of your element","register":null,"definition_en":"to be in a situation that makes you uncomfortable or unhappy","translation":"قرار گرفتن در موقعیتی که باعث ناراحتی یا ناراحتی شما می شود","example":"She was out of her element in this dull little town.","example_translation":"او در این شهر کوچولوی کسل کننده از حالت خود خارج شده بود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001184354.mp3"}]'::jsonb),
