('8f410af0-d5db-554f-87e5-87a75e08459f','e0581fa9-9805-53ee-984f-a3966441a916',1,'adverb','A2','S1','W1',null,'[{"phrase":"take something further","register":null,"definition_en":"to take action at a more serious or higher level , especially in order to get the result you want","translation":"برای دستیابی به نتیجه ای که می خواهید در سطح جدی تر یا بالاتر اقدام کنید","example":"The police do not propose to take the matter further .","example_translation":"پلیس پیشنهادی برای ادامه این موضوع ندارد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705711.mp3"},{"phrase":"further to something","register":"written","definition_en":"used in letters to mention a previous letter, conversation etc about the same matter","translation":"در نامه ها برای ذکر نامه قبلی، مکالمه و غیره در مورد همان موضوع استفاده می شود","example":"Further to your letter of February 5th, we can confirm your order.","example_translation":"علاوه بر نامه شما در تاریخ 5 فوریه، ما می توانیم سفارش شما را تایید کنیم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316679.mp3"},{"phrase":"nothing could be further from the truth","register":null,"definition_en":"used when you want to say that something is completely untrue","translation":"زمانی استفاده می شود که می خواهید بگویید چیزی کاملاً نادرست است","example":"People often described him as a bitter academic, but nothing could be further from the truth.","example_translation":"مردم اغلب او را به عنوان یک آکادمیک تلخ توصیف می کردند، اما هیچ چیز نمی تواند دور از واقعیت باشد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705731.mp3"},{"phrase":"something must not go any further","register":null,"definition_en":"used to say that something you are telling someone is secret or private","translation":"می گفت چیزی که به کسی می گویید مخفی یا خصوصی است","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
