('d6926c36-2292-575b-9e21-85cd06c6d3b8','48959d9d-03d3-5a9e-9db2-38966d3f26af',1,'noun','B2',null,'W2',null,'[{"phrase":"miscarriage of justice","register":null,"definition_en":"a situation in which someone is wrongly punished by a court of law for something they did not do","translation":"وضعیتی که در آن کسی به اشتباه توسط دادگاه قانون برای کاری که انجام نداده مجازات می شود","example":"the victim of a serious miscarriage of justice","example_translation":"قربانی یک تخلف جدی قضایی","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001761313.mp3"},{"phrase":"poetic justice","register":null,"definition_en":"a situation in which someone suffers , and you think they deserve it because they did something bad","translation":"موقعیتی که در آن کسی رنج می‌برد، و شما فکر می‌کنید او سزاوار آن است زیرا کار بدی انجام داده است","example":"After the way she treated Sam, it’s only poetic justice that Dave left her.","example_translation":"پس از نحوه رفتار او با سام، دیو تنها عدالت شاعرانه را ترک کرد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000343104.mp3"},{"phrase":"do yourself justice","register":null,"definition_en":"to do something such as a test well enough to show your real ability","translation":"انجام کاری مانند آزمون به اندازه کافی برای نشان دادن توانایی واقعی شما","example":"Sara panicked in the exam and didn’t do herself justice.","example_translation":"سارا در امتحان سراسیمه بود و عدالت را رعایت نکرد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001433043.mp3"}]'::jsonb),
