('a2bd3b45-619a-50c1-bcd6-935cc8158ca7','187c6ca1-e1dd-52a9-b61a-a4f483a5389e',2,'noun','B1',null,'W2','[ countable ]','[{"phrase":"be a measure of something","register":"formal","definition_en":"be a sign of the importance , strength etc of something, or a way of testing or judging something","translation":"نشانه ای از اهمیت، قدرت و غیره چیزی باشد، یا راهی برای آزمایش یا قضاوت چیزی باشد","example":"The flowers and tears at the funeral were a measure of the people’s love for her.","example_translation":"گل‌ها و اشک‌ها در مراسم تشییع جنازه نشانگر عشق مردم به او بود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216607.mp3"},{"phrase":"a measure of something","register":null,"definition_en":"an amount of something good or something that you want, for example success or freedom","translation":"مقداری از چیز خوب یا چیزی که شما می خواهید، برای مثال موفقیت یا آزادی","example":"The new law gives local governments a significant measure of control over their own finances.","example_translation":"قانون جدید به دولت های محلی کنترل قابل توجهی بر امور مالی خود می دهد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714650.mp3"},{"phrase":"for good measure","register":null,"definition_en":"in addition to what you have already done, given, or included","translation":"علاوه بر کارهایی که قبلاً انجام داده اید، داده اید یا گنجانده اید","example":"Why don’t you try phoning them one more time, for good measure?","example_translation":"چرا برای اندازه گیری خوب، یک بار دیگر با آنها تماس نمی گیرید؟","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216625.mp3"},{"phrase":"beyond measure","register":null,"definition_en":"very much or very great – used when you want to emphasize what you are saying","translation":"خیلی زیاد یا خیلی عالی – زمانی استفاده می شود که می خواهید بر چیزی که می گویید تأکید کنید","example":"Her work has improved beyond measure .","example_translation":"کار او بیش از حد پیشرفت کرده است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216620.mp3"},{"phrase":"the full measure of something","register":"formal","definition_en":"the whole of something","translation":"کل چیزی","example":"Ralph received the full measure of his mother’s devotion.","example_translation":"رالف تمام میزان فداکاری مادرش را دریافت کرد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216641.mp3"},{"phrase":"tape measure","register":null,"definition_en":"a long narrow band of cloth or steel , marked with centimetres , feet etc, used for measuring something","translation":"نوار باریک طولانی از پارچه یا فولاد، که با سانتی متر، پا و غیره مشخص شده است، که برای اندازه گیری چیزی استفاده می شود","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
