('cbdd6aaa-0406-588c-962c-4673ebefa513','86eec619-026f-53fd-822b-b4c0a2f9dae2',1,'noun','A1','S1','W1','[ countable ]','[{"phrase":"the meeting","register":"formal","definition_en":"all the people who are at a meeting","translation":"همه افرادی که در یک جلسه هستند","example":"I’d like to put a few ideas before the meeting.","example_translation":"من می خواهم چند ایده را قبل از جلسه مطرح کنم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000220597.mp3"},{"phrase":"meeting of minds","register":null,"definition_en":"a situation in which two people have very similar ideas and understand each other very well","translation":"موقعیتی که در آن دو نفر ایده های بسیار مشابهی دارند و به خوبی یکدیگر را درک می کنند","example":"There was a real meeting of minds between the two leaders.","example_translation":"یک ملاقات واقعی ذهنی بین دو رهبر وجود داشت.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000220611.mp3"}]'::jsonb),
