('4148b6ed-6803-5998-b3ff-ee37a2012bb9','0cd89468-56b3-5e54-83fe-7fb5ef7a17b8',1,'noun','A1','S2','W2',null,'[{"phrase":"by mistake","register":null,"definition_en":"if you do something by mistake , you do it without intending to","translation":"اگر کاری را به اشتباه انجام دهید، آن را بدون قصد انجام می دهید","example":"Someone must have left the door open by mistake.","example_translation":"حتما یک نفر به اشتباه در را باز گذاشته است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000202940.mp3"},{"phrase":"we all make mistakes","register":"spoken","definition_en":"used to tell someone not to be worried because they have made a mistake","translation":"به کسی می گفت نگران نباش چون اشتباه کرده است","example":"","example_translation":"","example_audio_url":""},{"phrase":"and no mistake","register":"spoken informal","definition_en":"used to emphasize the description you have just given","translation":"برای تأکید بر توصیفی که به تازگی ارائه کرده اید استفاده می شود","example":"Miles was a heartbreaker, and no mistake!","example_translation":"مایلز دلخراش بود و اشتباهی نبود!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000202985.mp3"}]'::jsonb),
