('8297b6eb-8463-5e29-ad9f-f9a195b01483','6a0ad0f8-901b-5b9d-b82b-b3cc0b628ae6',1,'noun','A2','S3','W2','[ countable ]','[{"phrase":"the old-boy network","register":null,"definition_en":"the system by which men who went to the same school , belong to the same club etc use their influence to help each other","translation":"سیستمی که بر اساس آن مردانی که به یک مدرسه می‌روند، متعلق به یک باشگاه هستند و غیره از نفوذ خود برای کمک به یکدیگر استفاده می‌کنند","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
