('907b8e1b-5295-55b4-bde0-204e8f4c5b65','9f9366c2-4e1d-53ac-b488-a5f6c40d1dde',1,'pronoun','A1','S1','W1',null,'[{"phrase":"nothing but","register":null,"definition_en":"only","translation":"فقط","example":"She’d had nothing but bad luck.","example_translation":"او چیزی جز بدشانسی نداشت.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572927.mp3"},{"phrase":"for nothing","register":null,"definition_en":"without paying for something or being paid for something","translation":"بدون اینکه برای چیزی پول بپردازید یا برای چیزی پول دریافت کنید","example":"Why pay a plumber when my brother will do it for nothing?","example_translation":"چرا به یک لوله کش پول بدهم وقتی برادرم این کار را بیهوده انجام می دهد؟","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000247704.mp3"},{"phrase":"come to nothing","register":null,"definition_en":"if a plan or action comes to nothing, it does not continue or does not achieve anything","translation":"اگر طرح یا اقدامی به نتیجه نرسد، ادامه پیدا نمی کند یا به چیزی نمی رسد","example":"","example_translation":"","example_audio_url":""},{"phrase":"be nothing if not something","register":null,"definition_en":"used to emphasize a particular quality that someone or something has","translation":"برای تأکید بر کیفیت خاصی که کسی یا چیزی دارد استفاده می شود","example":"You’ve got to admit – he’s nothing if not persistent.","example_translation":"باید اعتراف کنید - او اگر پیگیر نباشد، چیزی نیست.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572964.mp3"},{"phrase":"nothing doing","register":"spoken","definition_en":"used to refuse to do something","translation":"از انجام کاری امتناع می کرد","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
('2ec22e1d-b6a2-5507-91e3-3ebfe5e0c978','9f9366c2-4e1d-53ac-b488-a5f6c40d1dde',2,'adverb','A1',null,null,null,'[{"phrase":"be nothing less than something","register":null,"definition_en":"used to emphasize that something or someone has a particular quality or seems to be something","translation":"برای تأکید بر اینکه چیزی یا شخصی کیفیت خاصی دارد یا به نظر می رسد چیزی است استفاده می شود","example":"His behaviour was nothing short of rudeness.","example_translation":"رفتارش چیزی کمتر از بی ادبی نبود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000247822.mp3"}]'::jsonb),
