('90d75cf5-17cb-52f0-9bfa-b693002def0f','1950eb5c-3b05-5d0a-834a-41cf9ff67386',1,null,null,'spoken & written','to tell someone about something in a way that is clear or easy to understand',null,null,'توضیح دادن، شرح دادن؛ توجیه کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He carefully explained the procedure.","translation":"او با دقت روش را توضیح داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196398.mp3"},{"sentence":"The librarian will explain how to use the catalogue system.","translation":"کتابدار نحوه استفاده از سیستم فهرست را توضیح خواهد داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196401.mp3"},{"sentence":"Let me explain what I mean.","translation":"بگذارید منظورم را توضیح دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653577.mp3"},{"sentence":"He explained that it had been a difficult film to make.","translation":"او توضیح داد که ساخت این فیلم سخت بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196404.mp3"},{"sentence":"I explained the situation to my bank manager.","translation":"وضعیت را برای مدیر بانکم توضیح دادم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196407.mp3"}]'::jsonb,5),
('ec88fd0b-d668-5c2a-8294-11b345b9a2cf','1950eb5c-3b05-5d0a-834a-41cf9ff67386',2,null,null,'spoken & written','to give a reason for something or to be a reason for something',null,null,'دلیل آوردن برای چیزی یا دلیل بودن برای چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Wait! I can explain everything.","translation":"صبر کن من می توانم همه چیز را توضیح دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196411.mp3"},{"sentence":"How can you explain that sort of behaviour?","translation":"چگونه می توانید این نوع رفتار را توضیح دهید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653582.mp3"},{"sentence":"She explained that she had been ill.","translation":"او توضیح داد که بیمار بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196414.mp3"},{"sentence":"I’ll explain why I don’t believe your story.","translation":"توضیح خواهم داد که چرا داستان شما را باور نمی کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653583.mp3"},{"sentence":"That still doesn’t explain how he was able to hide the body.","translation":"این هنوز توضیح نمی دهد که چگونه او توانست جسد را پنهان کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653585.mp3"}]'::jsonb,5),
