('298c7e90-45d5-52f1-bdd6-ee5e19262bb4','bf79c4a8-d119-528a-9335-e5a2d3315589',1,null,null,'spoken & written','to discuss or think about something carefully','[ transitive ]',null,'بررسی کردن (گزینه‌ها)؛ اکتشاف کردن؛ سفر اکتشافی',array['look at']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Management need to explore ways of improving office security.","translation":"مدیریت باید راه های بهبود امنیت دفتر را بررسی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001197883.mp3"},{"sentence":"I’m going to explore the possibility of a part-time job.","translation":"من قصد دارم امکان کار پاره وقت را بررسی کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001657617.mp3"}]'::jsonb,2),
('189d01d3-46d2-50e1-816b-cd6d97d39b99','bf79c4a8-d119-528a-9335-e5a2d3315589',2,null,null,'spoken & written','to travel around an area in order to find out about it','[ intransitive, transitive ]',null,'به دور یک منطقه سفر کنید تا در مورد آن اطلاعات کسب کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Venice is a wonderful city to explore.","translation":"ونیز یک شهر شگفت انگیز برای کشف است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001197876.mp3"}]'::jsonb,1),
