('88fc6312-bc27-59d0-b8d7-558f5cfca7fc','3eff2405-16d7-5d95-8ea6-dc2f4f852a0f',1,null,null,'spoken & written','very great in degree','[ only before noun ]',null,'بسیار زیاد (درجه)؛ شدید و خشن (اقلیم)؛ افراطی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Extreme poverty still exists in many rural areas.","translation":"فقر شدید هنوز در بسیاری از مناطق روستایی وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001202948.mp3"},{"sentence":"It is necessary to use extreme caution with chemicals.","translation":"لازم است در مصرف مواد شیمیایی احتیاط شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001627642.mp3"},{"sentence":"extreme cold","translation":"سرمای شدید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001627646.mp3"},{"sentence":"He had extreme difficulty getting hold of the ingredients.","translation":"او در گرفتن مواد اولیه مشکل داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001832340.mp3"}]'::jsonb,4),
('fd584101-489d-5795-8aff-db333f8d15c2','3eff2405-16d7-5d95-8ea6-dc2f4f852a0f',2,null,null,'spoken & written','very unusual and severe or serious',null,null,'بسیار غیرعادی و شدید یا جدی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an extreme case of cruelty","translation":"یک مورد شدید از ظلم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001202963.mp3"},{"sentence":"Force is only justified in extreme circumstances .","translation":"زور فقط در شرایط شدید توجیه می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001627647.mp3"}]'::jsonb,2),
('730d77b0-fcaf-5ce8-b2d5-6e9199a2953f','3eff2405-16d7-5d95-8ea6-dc2f4f852a0f',3,null,null,'spoken & written',null,null,'extreme west/end/left etc','بسیار زیاد (درجه)؛ شدید و خشن (اقلیم)؛ افراطی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5ac87332-b9c4-5ede-b7e8-44d5ab209478','3eff2405-16d7-5d95-8ea6-dc2f4f852a0f',4,null,null,'spoken & written','extreme opinions , beliefs , or organizations , especially political ones, are considered by most people to be unacceptable and unreasonable',null,null,'عقاید افراطی، عقاید، یا سازمان ها، به ویژه عقاید سیاسی، توسط اکثر مردم غیرقابل قبول و غیر منطقی تلقی می شوند.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"extreme right-wing nationalists","translation":"ناسیونالیست های راست افراطی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001202956.mp3"}]'::jsonb,1),
('c586a0b5-fa1b-5fe2-87a2-a39a12cc2e5e','3eff2405-16d7-5d95-8ea6-dc2f4f852a0f',5,null,null,'spoken & written',null,null,'extreme sports/surfing/skiing etc','بسیار زیاد (درجه)؛ شدید و خشن (اقلیم)؛ افراطی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
