('68ffe829-37c8-5ec9-aa95-9ab8b207fe9e','cf780088-f2af-5b61-8257-597a0b8c1fa7',1,null,null,'spoken & written','to include or show something as a special or important part of something, or to be included as an important part','[ intransitive, transitive ]',null,'به‌نمایش گذاشتن؛ شامل بودن (ویژه)؛ نقش داشتن (در)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The exhibition features paintings by Picasso.","translation":"در این نمایشگاه نقاشی هایی از پیکاسو به نمایش گذاشته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001238096.mp3"},{"sentence":"a cruise ship featuring extensive spa facilities","translation":"یک کشتی کروز با امکانات گسترده آبگرم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644062.mp3"},{"sentence":"A study of language should feature in an English literature course.","translation":"مطالعه زبان باید در دوره ادبیات انگلیسی باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644063.mp3"},{"sentence":"Pupils visited some of the websites featured in the article.","translation":"دانش آموزان از برخی از وب سایت های ارائه شده در مقاله بازدید کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644066.mp3"},{"sentence":"Violence seems to feature heavily in all of his books.","translation":"به نظر می رسد خشونت در همه کتاب های او به شدت دیده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001238107.mp3"},{"sentence":"The film featured Brando as the Godfather.","translation":"در این فیلم براندو در نقش پدرخوانده ظاهر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001238100.mp3"}]'::jsonb,6),
('4b6f21c0-243f-5e8a-8d1c-a7aac3bff872','cf780088-f2af-5b61-8257-597a0b8c1fa7',2,null,null,'spoken & written','to show a film, play etc','[ transitive ]',null,'برای نمایش فیلم، نمایش و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Retro Theatre is featuring films by Frank Capra this week.","translation":"The Retro Theater این هفته فیلم هایی از فرانک کاپرا را به نمایش می گذارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001238121.mp3"}]'::jsonb,1),
('1abac8df-8f52-504e-8fb1-52ed85fde215','ee63817d-827f-5b36-8276-b9b3ad11a653',1,null,null,'spoken & written','a federal country or system of government consists of a group of states which control their own affairs , but which are also controlled by a single national government which makes decisions on foreign affairs, defence etc',null,null,'فدرال، دولت فدرال','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Switzerland is a federal republic.","translation":"سوئیس یک جمهوری فدرال است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001238899.mp3"}]'::jsonb,1),
('57d63b1f-a37d-5326-818c-4129f71e907f','ee63817d-827f-5b36-8276-b9b3ad11a653',2,null,null,'spoken & written','relating to the central government of a country such as the US, rather than the government of one of its states',null,null,'مربوط به دولت مرکزی کشوری مانند ایالات متحده است، نه دولت یکی از ایالت های آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"federal law","translation":"قانون فدرال","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001238903.mp3"},{"sentence":"federal taxes","translation":"مالیات های فدرال","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644082.mp3"}]'::jsonb,2),
('5c786435-ae77-5cf5-8bcc-a677ad4eafd9','f37d8eac-fa6e-554d-88d5-f002aedf8ae9',1,'anger/sadness/joy etc','خشم / غم / شادی و غیره','spoken & written','an emotion that you feel, such as anger , sadness , or happiness','[ countable ]',null,'احساس؛ نگرانی؛ حواس (لمسی)','{}'::text[],'{}'::text[],array['a good/great/wonderful etc feeling It''s a great feeling when you try something new and it works.','deep A deep feeling of sadness came over her.','strong/intense There was a strong feeling of anger among the workers.','experience a feeling I remember experiencing a feeling of tremendous excitement.','give somebody a feeling My work gives me a feeling of achievement.','arouse a feeling (= cause it ) The music aroused a feeling of calm within him.','hurt somebody''s feelings (= make someone feel upset ) I hope I didn''t hurt your feelings.','hide your feelings She could no longer hide her feelings.','show your feelings I know you find it embarrassing to show your feelings.','express your feelings ( also put your feelings into words ) (= tell other people what you are feeling or thinking ) Children sometimes find it difficult to put their feelings into words.','have mixed feelings (= have both positive and negative feelings ) Her parents had mixed feelings about the marriage.','feelings are running high (= people have strong feelings, especially of anger ) It was the last game of the season, and feelings were running high.']::text[],'[{"sentence":"Knowing we''d won was a wonderful feeling.","translation":"دانستن اینکه پیروز شده ایم احساس فوق العاده ای بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000571.mp3"},{"sentence":"a terrible feeling of guilt","translation":"احساس گناه وحشتناک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000572.mp3"}]'::jsonb,2),
('f4e4be0e-be70-5c54-967e-cb9562fa2fc3','f37d8eac-fa6e-554d-88d5-f002aedf8ae9',2,null,null,'spoken & written',null,null,'feelings','احساس؛ نگرانی؛ حواس (لمسی)','{}'::text[],'{}'::text[],array['a good/great/wonderful etc feeling It''s a great feeling when you try something new and it works.','deep A deep feeling of sadness came over her.','strong/intense There was a strong feeling of anger among the workers.','experience a feeling I remember experiencing a feeling of tremendous excitement.','give somebody a feeling My work gives me a feeling of achievement.','arouse a feeling (= cause it ) The music aroused a feeling of calm within him.','hurt somebody''s feelings (= make someone feel upset ) I hope I didn''t hurt your feelings.','hide your feelings She could no longer hide her feelings.','show your feelings I know you find it embarrassing to show your feelings.','express your feelings ( also put your feelings into words ) (= tell other people what you are feeling or thinking ) Children sometimes find it difficult to put their feelings into words.','have mixed feelings (= have both positive and negative feelings ) Her parents had mixed feelings about the marriage.','feelings are running high (= people have strong feelings, especially of anger ) It was the last game of the season, and feelings were running high.']::text[],'[]'::jsonb,0),
('93ee6b91-6429-5272-b866-48d79e6eeccd','f37d8eac-fa6e-554d-88d5-f002aedf8ae9',3,'opinion','نظر','spoken & written','a belief or opinion about something, especially one that is influenced by your emotions','[ countable ]',null,'یک باور یا نظر در مورد چیزی، به خصوص عقیده ای که تحت تأثیر احساسات شماست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My personal feeling is that not enough has been done.","translation":"احساس شخصی من این است که به اندازه کافی انجام نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001244010.mp3"},{"sentence":"She has strong feelings on the issue of abortion.","translation":"او احساسات شدیدی در مورد موضوع سقط جنین دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001244013.mp3"},{"sentence":"a survey on people’s feelings about the candidates","translation":"نظرسنجی در مورد احساسات مردم در مورد نامزدها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001244016.mp3"},{"sentence":"His gut feeling (= opinion based on emotion ) was that Burns was probably guilty.","translation":"احساس درونی او (= نظر بر اساس احساسات) این بود که برنز احتمالاً مقصر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001644325.mp3"},{"sentence":"I had this funny feeling (= not easily explained ) that something was wrong.","translation":"من این احساس خنده دار را داشتم (= به راحتی قابل توضیح نیست) که چیزی اشتباه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000573.mp3"}]'::jsonb,5),
