('808b6aa1-1e9c-57d4-8c1e-3b21fb3deb08','932aedcf-320c-59e9-a505-159c8ac36adc',4,null,null,'spoken & written','a quality or feature that makes something have a particular style or character','[ singular ]',null,'کیفیت یا ویژگی که باعث می شود چیزی سبک یا شخصیت خاصی داشته باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The stories have a strong regional flavour.","translation":"داستان ها طعم قوی منطقه ای دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001215381.mp3"},{"sentence":"Critics claim the building would destroy the flavor of the neighborhood.","translation":"منتقدان ادعا می کنند که این ساختمان طعم محله را از بین می برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001746865.mp3"}]'::jsonb,2),
