('38b49086-a482-55c9-8a2a-248427b737bf','ddeafdbb-b3c7-5864-af5b-0cf034e1dcbb',1,null,null,'spoken & written','for all future time',null,null,'برای همیشه، ابدی؛ دائماً','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I wanted that moment to last forever .","translation":"دلم می خواست آن لحظه برای همیشه ادامه داشته باشد .","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001270703.mp3"},{"sentence":"Many valuable works of art were lost forever.","translation":"بسیاری از آثار هنری ارزشمند برای همیشه گم شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001270704.mp3"}]'::jsonb,2),
('73ac2824-1fe7-58ed-89a0-4487d730937b','ddeafdbb-b3c7-5864-af5b-0cf034e1dcbb',2,null,null,'especially spoken','for a very long time',null,null,'برای مدت بسیار طولانی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Once built, stone walls last forever.","translation":"پس از ساخته شدن، دیوارهای سنگی برای همیشه باقی می مانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001270709.mp3"},{"sentence":"It took forever to clean up after the party.","translation":"تمیز کردن بعد از مهمانی برای همیشه طول کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751590.mp3"},{"sentence":"The meeting seemed to go on forever and a day .","translation":"به نظر می رسید جلسه برای همیشه و یک روز ادامه دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751594.mp3"}]'::jsonb,3),
