('d29be282-27ac-5982-bf98-d15df9b29775','18af47d7-6faa-594c-af37-70ddbb9af477',1,null,null,'spoken','to stop being angry with someone and stop blaming them, although they have done something wrong',null,null,'بخشیدن، عفو کردن؛ چشم‌پوشی (از بدهی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’ve tried to forgive him for what he said.","translation":"من سعی کردم او را به خاطر صحبت هایش ببخشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751725.mp3"},{"sentence":"He never forgave her for walking out on him.","translation":"او هرگز او را نبخشید که با او بیرون رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751726.mp3"},{"sentence":"If anything happened to the kids I’d never forgive myself .","translation":"اگر برای بچه ها اتفاقی بیفتد هرگز خودم را نمی بخشم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001271800.mp3"},{"sentence":"‘I’m really sorry.’ ‘It’s okay, you’re forgiven.’","translation":"\"من واقعا متاسفم.\" \"اشکالی ندارد، تو بخشیده شدی.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751734.mp3"},{"sentence":"God forgives us our sins.","translation":"خداوند گناهان ما را می بخشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001271797.mp3"},{"sentence":"He didn’t look the sort of man to forgive and forget (= forgive someone and no longer think about it ) .","translation":"به نظر مردی نبود که ببخشد و فراموش کند (= کسی را ببخش و دیگر به آن فکر نکن).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001751735.mp3"},{"sentence":"Alright, I forgive you.","translation":"باشه میبخشمت","audio_url":null},{"sentence":"Please forgive his rudeness.","translation":"لطفا بی ادبی او را ببخشید.","audio_url":null},{"sentence":"She lied and I can’t forgive her for that.","translation":"او دروغ گفت و من نمی توانم او را به خاطر آن ببخشم.","audio_url":null},{"sentence":"Forgive me for not writing.","translation":"منو ببخش که ننوشتم","audio_url":null},{"sentence":"Forgive us our trespasses.","translation":"تقصیرات ما را ببخش","audio_url":null}]'::jsonb,11),
