('2e497414-3242-5a44-83f6-b0c56cbef42d','bd077c16-8a1e-5309-a845-d9bd7134e983',1,null,null,'spoken & written','towards a place or position that is in front of you',null,null,'به جلو، پیش‌رو؛ فراتر (به آینده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He leaned forward , his elbows resting on the table.","translation":"به جلو خم شد و آرنج هایش را روی میز قرار داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001274819.mp3"},{"sentence":"The crowd surged forwards.","translation":"جمعیت به سمت جلو حرکت کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001274820.mp3"},{"sentence":"She took another small step forward.","translation":"او یک قدم کوچک دیگر به جلو برداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731215.mp3"}]'::jsonb,3),
('f2368bec-6306-59e6-8548-cc8100943edf','bd077c16-8a1e-5309-a845-d9bd7134e983',2,null,null,'spoken & written','towards greater progress , improvement , or development',null,null,'به سمت پیشرفت، بهبود یا توسعه بیشتر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We agreed that the sensible way forward was for a new company to be formed.","translation":"ما توافق کردیم که راه معقول پیش روی این است که یک شرکت جدید تشکیل شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001274825.mp3"},{"sentence":"After the Labour Party conference, he stated that we could now go forward as a united party.","translation":"او پس از کنفرانس حزب کارگر اظهار داشت که اکنون می توانیم به عنوان یک حزب متحد جلو برویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731219.mp3"},{"sentence":"Britain is now ready to move forward .","translation":"بریتانیا اکنون آماده حرکت به جلو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001731223.mp3"}]'::jsonb,3),
('0a2fccf1-b243-51c3-9b89-ad4b3abc51c0','bd077c16-8a1e-5309-a845-d9bd7134e983',3,null,null,'spoken & written','towards the future in a way that is hopeful',null,null,'به سوی آینده به گونه ای که امیدوار کننده باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I felt that at last I could begin to look forward .","translation":"احساس کردم بالاخره می توانم به آینده نگاه کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002087544.mp3"}]'::jsonb,1),
