('eb39756c-b513-5137-8e06-325dabf1c3c9','decd3d5f-2c0f-5b0d-8422-5b7bdfc5ba20',1,null,null,'spoken & written','a religious ceremony for burying or cremating (= burning ) someone who has died',null,null,'مراسم تدفین، تشییع جنازه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The funeral will be held at St. Martin’s Church.","translation":"مراسم تشییع جنازه در کلیسای سنت مارتین برگزار خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001315801.mp3"},{"sentence":"Hundreds of mourners attended the funeral of the two boys.","translation":"صدها نفر از مردم عزادار در مراسم تشییع جنازه این دو پسر شرکت کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705508.mp3"},{"sentence":"the minister who conducted the funeral service","translation":"وزیری که مراسم تشییع جنازه را برگزار کرد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705514.mp3"},{"sentence":"Nelson’s funeral procession down the Thames","translation":"مراسم تشییع جنازه نلسون در رودخانه تیمز","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824329.mp3"},{"sentence":"Ramdas set fire to the funeral pyre .","translation":"رامداس آتش سوزی تشییع جنازه را به آتش کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705515.mp3"}]'::jsonb,5),
