('b61948dc-8ff1-5f70-82f9-57a6f6bc91f2','8f410af0-d5db-554f-87e5-87a75e08459f',3,'distance','فاصله','spoken & written','a greater distance , or beyond a particular place',null,null,'یک فاصله بیشتر، یا فراتر از یک مکان خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They walked a little further.","translation":"کمی جلوتر رفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705719.mp3"},{"sentence":"His farm is located further away from Riobamba than his brother’s.","translation":"مزرعه او دورتر از ریوبامبا نسبت به مزرعه برادرش قرار دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705720.mp3"},{"sentence":"His hands moved further down her back.","translation":"دستانش بیشتر به سمت پایین پشتش حرکت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705721.mp3"},{"sentence":"They’ve never been further south than San Diego.","translation":"آنها هرگز از سن دیگو در جنوب نبوده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001705722.mp3"}]'::jsonb,4),
('3b3956ec-60ab-598e-b01a-434ef5584de0','8f410af0-d5db-554f-87e5-87a75e08459f',4,'time','زمان','spoken & written','into the past or the future',null,null,'به گذشته یا آینده','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Five years further on, a cure has still not been found.","translation":"پنج سال بعد، هنوز درمانی پیدا نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316653.mp3"},{"sentence":"The records don’t go any further back than 1960.","translation":"رکوردها به سال 1960 بیشتر نمی رسند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316654.mp3"},{"sentence":"It might be a sign, much further down the road (= in the future ) , of a change in policy.","translation":"این ممکن است نشانه ای از تغییر در سیاست باشد، بسیار پایین تر (= در آینده).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316658.mp3"}]'::jsonb,3),
('42a04b88-cfbc-566e-81e6-6d7db784e1a8','8f410af0-d5db-554f-87e5-87a75e08459f',5,'in addition','علاوه بر این','formal','used to introduce something additional that you want to talk about','[ sentence adverb ]',null,'برای معرفی چیز دیگری استفاده می شود که می خواهید در مورد آن صحبت کنید',array['furthermore']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Butter sales have fallen because margarine has improved in flavor. Further, butter consumption has decreased because of links to heart disease.","translation":"فروش کره کاهش یافته است زیرا مارگارین از نظر طعم بهبود یافته است. علاوه بر این، مصرف کره به دلیل ارتباط با بیماری قلبی کاهش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001316673.mp3"}]'::jsonb,1),
