('9b4900fe-ae0b-51bd-ac06-245971344bbe','7475a5b1-646b-59a2-8006-60ff6e9a2a54',4,'behaviour/attitude','رفتار/نگرش','spoken & written','used to describe an attitude , feeling, or behaviour that is natural , normal , and sensible',null,null,'برای توصیف یک نگرش، احساس یا رفتار طبیعی، عادی و معقول استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I don’t think it’s healthy for her to spend so much time alone.","translation":"فکر نمی کنم برای او سالم باشد که زمان زیادی را تنها بگذراند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001756801.mp3"},{"sentence":"a healthy disrespect for silly regulations","translation":"بی احترامی سالم به قوانین احمقانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001350849.mp3"}]'::jsonb,2),
