('b484e7f9-edca-5a87-9e36-7620241bf9ab','8973f383-e5a2-5407-b4d4-b49777dec5ed',1,null,null,'spoken & written','providing useful help in making a situation better or easier',null,null,'سودمند، مفید؛ خوش‌سلیقه (نکته)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Thank you for your advice; it’s been very helpful.","translation":"ممنون از راهنمایی شما؛ بسیار مفید بوده است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001725350.mp3"},{"sentence":"It is helpful to discuss your problems with your friends.","translation":"درمیان گذاشتن مشکلات خود با دوستانتان مفید است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001356271.mp3"},{"sentence":"It is helpful for family members to gain a basic understanding of the illness.","translation":"برای اعضای خانواده کمک کننده است تا درک اولیه ای از بیماری به دست آورند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001356272.mp3"},{"sentence":"It is helpful if we address a few key questions here.","translation":"اگر در اینجا به چند سوال کلیدی بپردازیم مفید خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001725353.mp3"},{"sentence":"We hope this leaflet has been helpful in answering your questions.","translation":"امیدواریم این جزوه در پاسخ به سوالات شما مفید بوده باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001356275.mp3"},{"sentence":"Our sales staff are there to give you helpful advice.","translation":"کارکنان فروش ما در آنجا هستند تا به شما مشاوره مفید بدهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001356278.mp3"}]'::jsonb,6),
('1dc57420-e630-5e22-bd50-9c2c6b5a4913','8973f383-e5a2-5407-b4d4-b49777dec5ed',2,null,null,'spoken & written','always willing to help people',null,null,'همیشه مایل به کمک به مردم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s a helpful child.","translation":"او یک کودک مفید است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001356282.mp3"},{"sentence":"I’m only trying to be helpful.","translation":"من فقط سعی می کنم مفید باشم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001725358.mp3"}]'::jsonb,2),
