('762d0808-d64d-56be-b408-85b9122fa15c','f839735b-43fa-5603-addb-d572a1659fab',2,null,null,'spoken & written','used to emphasize that you are talking about one particular woman or girl',null,null,'برای تأکید بر اینکه شما در مورد یک زن یا دختر خاص صحبت می کنید استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It must be true that she’s leaving because she told me so herself.","translation":"باید درست باشد که او می رود چون خودش این را به من گفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001379678.mp3"},{"sentence":"The ornate Town Hall was opened by Queen Victoria herself.","translation":"تالار شهر پرآذین توسط خود ملکه ویکتوریا افتتاح شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001379679.mp3"},{"sentence":"She met other mothers in the same situation as herself.","translation":"او مادران دیگری را در شرایطی مشابه خودش ملاقات کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837310.mp3"}]'::jsonb,3),
