('fd0f356b-8de5-51f0-bd13-c815f7810869','76d7a7af-db79-54a6-b9f8-cc20d7894cd6',1,null,null,'spoken & written','used to show that the man or boy who does something is affected by his own action',null,null,'خود او (نر) — ضمیر انعکاسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In despair, the young boy had hanged himself.","translation":"پسر جوان در ناامیدی خود را حلق آویز کرده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001383868.mp3"},{"sentence":"His name is James but he calls himself Jim.","translation":"نام او جیمز است اما خود را جیم می نامد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001383867.mp3"},{"sentence":"He poured himself a glass of orange juice.","translation":"یک لیوان آب پرتقال برای خودش ریخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726871.mp3"},{"sentence":"Everyone should learn to respect himself.","translation":"هر کس باید یاد بگیرد که به خودش احترام بگذارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837317.mp3"}]'::jsonb,4),
('a451a085-4265-57d4-8f0d-bdacc06103ab','76d7a7af-db79-54a6-b9f8-cc20d7894cd6',2,null,null,'spoken & written','used to emphasize that you are talking about one particular man or boy',null,null,'برای تأکید بر اینکه شما در مورد یک مرد یا پسر خاص صحبت می کنید استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was the president himself who opened the door.","translation":"این خود رئیس جمهور بود که در را باز کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001383835.mp3"},{"sentence":"It must be true – he said so himself.","translation":"این باید درست باشد - خودش این را گفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001383836.mp3"},{"sentence":"The other passengers were all refugees like himself.","translation":"مسافران دیگر همگی مانند خودش پناهنده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837321.mp3"}]'::jsonb,3),
