('3475fd40-72c2-5545-b0f4-0033fd956ebf','94cd0466-1c62-5e14-90a0-b3329834b2bf',1,null,null,'spoken & written','to spend your holiday in a place – used especially in news reports',null,null,'برای گذراندن تعطیلات خود در یک مکان - به ویژه در گزارش های خبری استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They’re holidaying in Majorca.","translation":"آنها در مایورکا تعطیلات می گذرانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001391844.mp3"}]'::jsonb,1),
('2cc70204-e544-519f-9d37-df5fb2f63e5e','6e4814a8-b809-5590-b72b-4ad70b2aab31',1,null,null,'spoken & written','the houses or conditions that people live in','[ uncountable ]',null,'مسکن، خانه‌داری؛ اسکان؛ بخش مسکن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"health problems caused by bad housing","translation":"مشکلات بهداشتی ناشی از مسکن بد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363600.mp3"},{"sentence":"a scheme to provide affordable housing for local people","translation":"طرحی برای ارائه مسکن ارزان قیمت برای مردم محلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709142.mp3"}]'::jsonb,2),
('04976445-de7d-526a-a34b-97d327f1c33e','6e4814a8-b809-5590-b72b-4ad70b2aab31',2,null,null,'spoken & written','the work of providing houses for people to live in','[ uncountable ]',null,'کار تهیه خانه برای زندگی مردم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"government housing policy","translation":"سیاست مسکن دولت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363605.mp3"},{"sentence":"public services such as education, housing and transport","translation":"خدمات عمومی مانند آموزش، مسکن و حمل و نقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001709143.mp3"}]'::jsonb,2),
('50575b2f-f272-5202-b10e-5a0a48aa8126','6e4814a8-b809-5590-b72b-4ad70b2aab31',3,null,null,'spoken & written','a protective cover for a machine','[ countable ]',null,'پوشش محافظ برای دستگاه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the engine housing","translation":"محفظه موتور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363610.mp3"}]'::jsonb,1),
('e9c429e8-e395-57b8-8b28-825b1b420be4','fbcbc1f9-771f-5c40-bd1e-e05354d5d47e',1,null,null,'spoken & written','used when you are adding a fact or piece of information that seems surprising , or seems very different from what you have just said',null,null,'با این حال، با وجود این؛ هر طور باشد',array['nevertheless']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This is a cheap and simple process. However, there are dangers.","translation":"این یک فرآیند ارزان و ساده است. با این حال، خطراتی وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363913.mp3"},{"sentence":"an extremely unpleasant disease that is, however, easy to treat","translation":"یک بیماری بسیار ناخوشایند که درمان آن آسان است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020092.mp3"}]'::jsonb,2),
('808d3951-ad70-5614-adcd-8df1ab67cce1','fbcbc1f9-771f-5c40-bd1e-e05354d5d47e',2,null,null,'spoken & written','used to say that it does not matter how big, good, serious etc something is because it will not change a situation in any way',null,null,'می گفت مهم نیست چیزی چقدر بزرگ، خوب، جدی و غیره باشد، زیرا به هیچ وجه شرایط را تغییر نمی دهد',array['no matter how']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You should report any incident, however minor it is.","translation":"شما باید هر حادثه ای را گزارش کنید، هر چند جزئی باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363925.mp3"},{"sentence":"We have to finish, however long it takes.","translation":"باید تمام کنیم، هر چقدر هم که طول بکشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363926.mp3"},{"sentence":"I really want the car, however much it costs.","translation":"من واقعاً ماشین را می خواهم، هر چقدر قیمتش باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363930.mp3"}]'::jsonb,3),
('7c8f5353-25c0-5c30-a579-a88204c44006','fbcbc1f9-771f-5c40-bd1e-e05354d5d47e',3,null,null,'spoken & written','used to show surprise when you ask how something happens or how someone does something',null,null,'زمانی که می‌پرسید چطور اتفاقی می‌افتد یا کسی چگونه کاری را انجام می‌دهد، تعجب نشان می‌داد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"However did he get that job?","translation":"با این حال آیا او آن شغل را بدست آورد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363934.mp3"}]'::jsonb,1),
('2f0192c4-f125-53a6-bbe2-50d835fe6f28','3c48e884-c517-510c-8c91-817b76433bac',1,null,null,'spoken & written','in whatever way',null,null,'به هر شکلی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You can do it however you like.","translation":"شما می توانید آن را هر طور که دوست دارید انجام دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363943.mp3"},{"sentence":"If we win the match, we’ll be delighted, however it happens.","translation":"اگر مسابقه را ببریم، خوشحال خواهیم شد، هر طور که اتفاق بیفتد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001363944.mp3"},{"sentence":"However you look at it, it was a wicked thing to do.","translation":"به هر حال که به آن نگاه می کنید، این کار زشتی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001814089.mp3"}]'::jsonb,3),
('3015e6f6-86f0-5928-970c-c446ec10cae6','7e2ca7a0-6185-5752-ba56-54e99fc8a01e',1,null,null,'spoken & written','the man that a woman is married to','[ countable ]',null,'شوهر، همسر (زن)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Have you met my husband Roy?","translation":"آیا با شوهرم روی ملاقات کردی؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001367371.mp3"}]'::jsonb,1),
