('93b758c4-51d7-534d-ac19-4a4e757561e8','225090c0-0091-5a0f-814b-5e07d6615979',1,null,null,'spoken & written',null,null,'instead of somebody/something','به‌جای، در عوض؛ بجای (اینکه)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('9f777e8d-5b09-59d6-8a32-3afb62932b4e','225090c0-0091-5a0f-814b-5e07d6615979',2,null,null,'spoken & written','used to say what is done, when you have just said that a particular thing is not done',null,null,'وقتی می‌گفتید کار خاصی انجام نشده است، می‌گفتند چه کاری انجام شده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Geoff didn’t study law. Instead, he decided to become an actor.","translation":"جف حقوق نخواند. در عوض تصمیم گرفت بازیگر شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417034.mp3"},{"sentence":"If Jo can’t attend the meeting, I could go instead.","translation":"اگر جو نتواند در جلسه شرکت کند، می توانم به جای آن بروم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001417030.mp3"}]'::jsonb,2),
('cde118c1-d1f7-5245-8e5f-d2081b0cc5f9','4d1c366e-4552-54ba-9246-5c24fd68b952',1,null,null,'spoken & written','having a very strong effect or felt very strongly',null,null,'شدید، تند (درد، آتش)؛ پرمخاطره (کار)','{}'::text[],'{}'::text[],array['intense pressure The prime minister is under intense pressure to call a general election.','intense competition There is intense competition for places on the course.','intense heat He could feel the intense heat of the Egyptian sun.','intense cold He was shivering with intense cold.','intense pain She felt an intense pain in her right shoulder.','intense pleasure Anne read the letter with intense pleasure.','an intense desire Fred felt an intense desire to punch Max in the face.','an intense interest in something The police are aware of the intense interest in the case.','intense dislike He had taken an intense dislike to Robert.','intense activity The opening of the restaurant was preceded by a period of intense activity.','intense debate Abortion has become the subject of intense debate.','intense negotiations The hostages were freed after intense negotiations.','intense scrutiny (= being examined very carefully ) The mining industry is coming under intense scrutiny over its environmental record.','intense speculation (= a lot of guessing about what may have happened ) After weeks of intense speculation, the actress announced that she was pregnant.','intense opposition Locals have voiced intense opposition to plans to expand the airport.','intense feelings/emotion Her lips trembled with intense emotion.']::text[],'[{"sentence":"Young people today are under intense pressure to succeed.","translation":"جوانان امروز برای موفقیت تحت فشار شدید هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721342.mp3"},{"sentence":"the intense heat of the desert","translation":"گرمای شدید کویر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001419208.mp3"},{"sentence":"The pain was so intense I couldn’t sleep.","translation":"درد آنقدر شدید بود که نمی توانستم بخوابم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721343.mp3"},{"sentence":"He took an intense interest in all religious matters.","translation":"علاقه شدیدی به همه امور دینی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721344.mp3"},{"sentence":"a look of intense dislike","translation":"نگاه نفرت شدید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721345.mp3"}]'::jsonb,5),
('b84fe8b7-ffeb-55b0-811b-a71f51f62af3','4d1c366e-4552-54ba-9246-5c24fd68b952',2,null,null,'spoken & written','intense activity is very serious , uses a lot of effort , and often involves doing a great deal in a very short time',null,null,'فعالیت شدید بسیار جدی است، از تلاش زیادی استفاده می کند، و اغلب شامل انجام کارهای زیادی در زمان بسیار کوتاه است.','{}'::text[],'{}'::text[],array['intense pressure The prime minister is under intense pressure to call a general election.','intense competition There is intense competition for places on the course.','intense heat He could feel the intense heat of the Egyptian sun.','intense cold He was shivering with intense cold.','intense pain She felt an intense pain in her right shoulder.','intense pleasure Anne read the letter with intense pleasure.','an intense desire Fred felt an intense desire to punch Max in the face.','an intense interest in something The police are aware of the intense interest in the case.','intense dislike He had taken an intense dislike to Robert.','intense activity The opening of the restaurant was preceded by a period of intense activity.','intense debate Abortion has become the subject of intense debate.','intense negotiations The hostages were freed after intense negotiations.','intense scrutiny (= being examined very carefully ) The mining industry is coming under intense scrutiny over its environmental record.','intense speculation (= a lot of guessing about what may have happened ) After weeks of intense speculation, the actress announced that she was pregnant.','intense opposition Locals have voiced intense opposition to plans to expand the airport.','intense feelings/emotion Her lips trembled with intense emotion.']::text[],'[{"sentence":"The job demands intense concentration.","translation":"کار نیاز به تمرکز شدید دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001419213.mp3"},{"sentence":"At least 3,000 people were killed in a week of intense fighting.","translation":"حداقل 3000 نفر در یک هفته درگیری شدید کشته شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001721347.mp3"}]'::jsonb,2),
('5f1a1f5b-6b95-57f4-85d8-4759166f037c','4d1c366e-4552-54ba-9246-5c24fd68b952',3,null,null,'spoken & written','someone who is intense is serious and has very strong feelings or opinions – used to show disapproval',null,null,'کسی که شدیداً جدی است و احساسات یا نظرات بسیار قوی دارد - برای نشان دادن مخالفت استفاده می شود','{}'::text[],'{}'::text[],array['intense pressure The prime minister is under intense pressure to call a general election.','intense competition There is intense competition for places on the course.','intense heat He could feel the intense heat of the Egyptian sun.','intense cold He was shivering with intense cold.','intense pain She felt an intense pain in her right shoulder.','intense pleasure Anne read the letter with intense pleasure.','an intense desire Fred felt an intense desire to punch Max in the face.','an intense interest in something The police are aware of the intense interest in the case.','intense dislike He had taken an intense dislike to Robert.','intense activity The opening of the restaurant was preceded by a period of intense activity.','intense debate Abortion has become the subject of intense debate.','intense negotiations The hostages were freed after intense negotiations.','intense scrutiny (= being examined very carefully ) The mining industry is coming under intense scrutiny over its environmental record.','intense speculation (= a lot of guessing about what may have happened ) After weeks of intense speculation, the actress announced that she was pregnant.','intense opposition Locals have voiced intense opposition to plans to expand the airport.','intense feelings/emotion Her lips trembled with intense emotion.']::text[],'[{"sentence":"She’s a little too intense for me.","translation":"او برای من کمی بیش از حد شدید است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001419217.mp3"}]'::jsonb,1),
('5c63e31e-8553-55ab-a48b-5c8006e0e16c','64174978-72e6-5f2d-8e7b-c5ff37212111',1,null,null,'spoken & written','if an activity or situation involves something, that thing is part of it or a result of it',null,null,'شامل بودن؛ درگیر کردن؛ نگران ساختن (دل)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"What will the job involve?","translation":"شغل شامل چه مواردی خواهد شد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001428115.mp3"},{"sentence":"I didn’t realize putting on a play involved so much work.","translation":"من نمی دانستم که اجرای یک نمایشنامه این همه کار را شامل می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001428116.mp3"},{"sentence":"Running your own business usually involves working long hours.","translation":"راه اندازی کسب و کار شخصی معمولاً مستلزم کار کردن ساعت های طولانی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724499.mp3"}]'::jsonb,3),
('a502a490-4d7b-578a-a357-342a0bcacb2a','64174978-72e6-5f2d-8e7b-c5ff37212111',2,null,null,'spoken & written','to include or affect someone or something',null,null,'شامل کردن یا تأثیر گذاشتن بر کسی یا چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"These changes will involve everyone on the staff.","translation":"این تغییرات همه کارکنان را درگیر خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001428123.mp3"},{"sentence":"There have been four accidents involving Forest Service planes.","translation":"چهار سانحه در هواپیماهای خدمات جنگلی رخ داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001724500.mp3"}]'::jsonb,2),
('b298e404-46a0-567e-9903-e4363d09ca7f','64174978-72e6-5f2d-8e7b-c5ff37212111',3,null,null,'spoken & written','to ask or allow someone to take part in something',null,null,'درخواست کردن یا اجازه دادن به کسی که در چیزی شرکت کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Try to involve as many children as possible in the game.","translation":"سعی کنید تا حد امکان کودکان را در بازی شرکت دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001428131.mp3"},{"sentence":"We want to involve the workforce at all stages of the decision-making process.","translation":"ما می خواهیم نیروی کار را در تمام مراحل فرآیند تصمیم گیری مشارکت دهیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001428132.mp3"}]'::jsonb,2),
('47d1cd91-d4c5-57bb-87f1-7df6a6a193aa','64174978-72e6-5f2d-8e7b-c5ff37212111',4,null,null,'spoken & written',null,null,'involve yourself','شامل بودن؛ درگیر کردن؛ نگران ساختن (دل)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('76f38b50-3779-5b14-b95a-c8bc5d62496f','36a2256f-1b1c-5267-840c-c55655cf5916',1,null,null,'spoken & written','an occasion when you travel from one place to another, especially over a long distance',null,null,'سفر، سفرنامه (مسافرت)؛ پرواز (مسافت)','{}'::text[],'{}'::text[],array['make a journey I still use my car, but now I make fewer journeys.','go on a journey (= make a long journey ) We are going on a journey to a strange country.','begin/start a journey He began the journey home across London.','set off on a journey ( also embark on a journey formal ) (= start a long journey ) Before setting off on a journey, look at maps and guidebooks.','break your journey (= make a short stop on a journey ) We broke our journey to have a picnic.','continue your journey We stopped for breakfast, then continued our journey.','a car/plane/bus etc journey the six-hour train journey to London','a long journey They arrived tired from their long journey.','a difficult journey It was a difficult journey, especially in the winter months.','a safe journey (= used especially to wish someone a good journey ) Have a safe journey.','an epic journey (= a very long and eventful journey ) Lewis and Clark made their epic journey across the continental United States in the early 1800s.','a wasted journey (= one that did not achieve the result you wanted ) To avoid a wasted journey, ring first to check that the event is still on.','a dangerous/hazardous/perilous journey They set off on the dangerous journey down the river.','an arduous journey (= to a place that is difficult to reach ) the arduous journey to the North Pole','the outward journey (= the journey to a place ) The outward journey seemed long and slow.','the return journey (= the journey back from a place ) The return journey was uneventful.','the homeward journey (= the journey back home ) In the car on their homeward journey, they discussed the wedding.','a leg/stage of a journey (= one part of a journey ) We set off on the final leg of our journey.']::text[],'[{"sentence":"my journey to China","translation":"سفر من به چین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730699.mp3"},{"sentence":"a journey across Europe","translation":"سفر در سراسر اروپا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000871.mp3"},{"sentence":"the friends they made on the journey","translation":"دوستانی که در سفر پیدا کردند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730707.mp3"}]'::jsonb,3),
('3df84b53-b988-5df2-8749-9b374437ac6d','36a2256f-1b1c-5267-840c-c55655cf5916',2,null,null,'literary','a long and often difficult process by which someone or something changes and develops',null,null,'یک فرآیند طولانی و اغلب دشوار که توسط آن شخص یا چیزی تغییر می کند و توسعه می یابد','{}'::text[],'{}'::text[],array['make a journey I still use my car, but now I make fewer journeys.','go on a journey (= make a long journey ) We are going on a journey to a strange country.','begin/start a journey He began the journey home across London.','set off on a journey ( also embark on a journey formal ) (= start a long journey ) Before setting off on a journey, look at maps and guidebooks.','break your journey (= make a short stop on a journey ) We broke our journey to have a picnic.','continue your journey We stopped for breakfast, then continued our journey.','a car/plane/bus etc journey the six-hour train journey to London','a long journey They arrived tired from their long journey.','a difficult journey It was a difficult journey, especially in the winter months.','a safe journey (= used especially to wish someone a good journey ) Have a safe journey.','an epic journey (= a very long and eventful journey ) Lewis and Clark made their epic journey across the continental United States in the early 1800s.','a wasted journey (= one that did not achieve the result you wanted ) To avoid a wasted journey, ring first to check that the event is still on.','a dangerous/hazardous/perilous journey They set off on the dangerous journey down the river.','an arduous journey (= to a place that is difficult to reach ) the arduous journey to the North Pole','the outward journey (= the journey to a place ) The outward journey seemed long and slow.','the return journey (= the journey back from a place ) The return journey was uneventful.','the homeward journey (= the journey back home ) In the car on their homeward journey, they discussed the wedding.','a leg/stage of a journey (= one part of a journey ) We set off on the final leg of our journey.']::text[],'[{"sentence":"our journey through life","translation":"سفر ما در زندگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001472748.mp3"},{"sentence":"The novel is an account of his spiritual journey.","translation":"این رمان روایتی از سفر معنوی اوست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730730.mp3"}]'::jsonb,2),
('c545fd2d-fe8b-5ad1-81e3-94950a680bbe','0369bb9d-cd24-509b-91b5-b883d9386868',1,null,null,'literary','to travel',null,null,'برای سفر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They left the town and journeyed south.","translation":"آنها شهر را ترک کردند و به جنوب رفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001730731.mp3"}]'::jsonb,1),
('860a8b20-3d60-52cf-b21c-2b043c9dd6c7','d6926c36-2292-575b-9e21-85cd06c6d3b8',1,'system of judgement','سیستم قضاوت','spoken & written','the system by which people are judged in courts of law and criminals are punished','[ uncountable ]','miscarriage of justice','عدالت، انصاف؛ قوّه قضاییه؛ قضاوت (عدالت‌محور)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a book on the criminal justice system","translation":"کتابی در مورد سیستم عدالت کیفری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001433017.mp3"},{"sentence":"The killers will be brought to justice (= caught and punished ) .","translation":"قاتلان محاکمه خواهند شد (= گرفتار و مجازات خواهند شد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755343.mp3"},{"sentence":"Acts of terrorism must not escape justice .","translation":"اقدامات تروریستی نباید از عدالت فرار کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755348.mp3"}]'::jsonb,3),
('8b52783f-447c-55f2-94ee-d4b312748425','d6926c36-2292-575b-9e21-85cd06c6d3b8',2,'fairness','انصاف','spoken & written','fairness in the way people are treated','[ uncountable ]','poetic justice','انصاف در نحوه برخورد با مردم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Children have a strong sense of justice .","translation":"کودکان احساس عدالت قوی دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001433004.mp3"},{"sentence":"His people came to him demanding justice .","translation":"مردمش با تقاضای عدالت نزد او آمدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001755360.mp3"}]'::jsonb,2),
