('0d7e2410-7d81-5610-a29d-04424d58f363','a97eee9d-23b9-5819-9248-0f1cd1b7da58',1,null,null,'spoken & written','willing to understand and respect other people’s ideas, opinions , and feelings',null,null,'آزاداندیش، لیبرال؛ بخشنده (مقدار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a more liberal attitude towards sexuality","translation":"نگرش آزادتر نسبت به تمایلات جنسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001458084.mp3"},{"sentence":"I had quite liberal parents.","translation":"من پدر و مادری کاملا لیبرال داشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001736893.mp3"}]'::jsonb,2),
('1d7dd807-629a-5e29-bc63-aca287b7d458','a97eee9d-23b9-5819-9248-0f1cd1b7da58',2,null,null,'spoken & written','supporting or allowing gradual political and social changes',null,null,'حمایت یا اجازه تغییرات تدریجی سیاسی و اجتماعی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a more liberal policy on issues of crime and punishment","translation":"یک سیاست لیبرال تر در مورد مسائل جرم و مجازات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001458088.mp3"}]'::jsonb,1),
