('d27643b4-0c7d-56ef-b528-c9a41514b155','a97eee9d-23b9-5819-9248-0f1cd1b7da58',4,null,null,'spoken & written','generous or given in large amounts',null,'liberally','سخاوتمندانه یا در مقادیر زیاد داده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a liberal supply of drinks","translation":"عرضه آزاد نوشیدنی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001458092.mp3"},{"sentence":"If only they were as liberal with their cash.","translation":"اگر فقط با پول نقد خود لیبرال بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001828847.mp3"}]'::jsonb,2),
