('ff0a34fc-070f-570c-98f0-aa5f0203c3f9','20fc0e4f-c158-5939-8380-bcbc81bdd751',1,null,null,'spoken & written','not very great in amount, number, ability etc',null,null,'محدود، ناچیز؛ (دسترسی) محدود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There are only a limited number of tickets available.","translation":"فقط تعداد محدودی بلیط موجود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001741914.mp3"},{"sentence":"My knowledge of the business is limited.","translation":"دانش من در مورد تجارت محدود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001741915.mp3"},{"sentence":"The organization has very limited resources .","translation":"سازمان منابع بسیار محدودی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001741916.mp3"},{"sentence":"So far, the education reforms have had only limited success .","translation":"تاکنون، اصلاحات آموزشی موفقیت محدودی داشته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001741920.mp3"},{"sentence":"Unfortunately, the drug is of limited value in treating cancer.","translation":"متاسفانه، این دارو در درمان سرطان ارزش محدودی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001741926.mp3"}]'::jsonb,5),
