('d308b71a-8a54-5afb-acd8-e1cc9934ee2e','134b818f-5b96-5644-aab2-8c3d7dfbfa5b',1,null,null,'spoken & written','seeming reasonable and sensible',null,null,'منطقی، درست‌اندیش؛ مرتبط (استدلال)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s a logical site for a new supermarket, with the housing development nearby.","translation":"این یک سایت منطقی برای یک سوپرمارکت جدید با توسعه مسکن در نزدیکی آن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001510723.mp3"},{"sentence":"a logical conclusion","translation":"یک نتیجه گیری منطقی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001510724.mp3"}]'::jsonb,2),
('835dc006-c121-5852-a1c2-71fdbe175b8b','134b818f-5b96-5644-aab2-8c3d7dfbfa5b',2,null,null,'spoken & written','using a thinking process in which facts and ideas are connected in a correct way',null,null,'با استفاده از یک فرآیند تفکر که در آن حقایق و ایده ها به روشی صحیح به هم متصل می شوند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The detective has to discover the murderer by logical deduction.","translation":"کارآگاه باید با استنتاج منطقی قاتل را کشف کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001510733.mp3"}]'::jsonb,1),
('b65e591d-a71c-5850-9fce-1ddd73dc8513','7d367d1d-c38c-5b32-84e2-ec375b486fd7',1,null,null,'spoken & written','used to say that it is good that something happened or was done because if it had not, the situation would be unpleasant or difficult','[ sentence adverb ]',null,'خوش‌اقبالی، خوش‌شانس؛ (تأکید) به‌خوش‌بختی',array['fortunately']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Luckily the museum was not damaged by the earthquake.","translation":"خوشبختانه موزه در اثر زلزله آسیب ندیده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001473861.mp3"},{"sentence":"Luckily for them, he braked in time.","translation":"خوشبختانه او به موقع ترمز کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001473864.mp3"}]'::jsonb,2),
('6fff8619-397a-545d-9c05-1954c33bab67','c5aea3a9-cf41-513d-8c5b-0a394ea8fab7',1,null,null,'spoken & written','a piece of equipment with moving parts that uses power such as electricity to do a particular job',null,'answering machine , cash machine , vending machine','ماشین، دستگاه؛ ماشین (سازوکار)','{}'::text[],'{}'::text[],array['switch on/turn on a machine Turn the machine on and slowly add the hot liquid.','switch off/turn off a machine Is the tape machine switched off?','operate/work a machine Have you been taught to operate the machine properly?','use a machine Can you use the copy machine?','a machine operates/works The machine works using solar power.','install a machine (= put it somewhere and connect it so it can be used ) 300 new machines have been installed across the country.','upgrade a machine (= add new and better parts to it or replace it with a better one ) How much will it cost to upgrade the machine?','a washing machine (= for washing clothes ) Put your dirty clothes straight in the washing machine.','a sewing machine Can I borrow your sewing machine to make some curtains?','an answering machine (= for recording telephone messages ) There’s a message on the answering machine.','a coffee machine (= for providing cups of coffee ) She was at the coffee machine last time I saw her.','a vending machine (= for supplying drinks, chocolate bars etc ) You can buy hot drinks from the vending machine in the corridor.','a cash/ATM machine (= for giving you money from your bank account ) I need to stop at a cash machine.','a slot machine (= for putting coins in in order to try and win more money ) The casino has 500 slot machines.','a life-support machine (= for keeping a very sick person alive ) He has been on a life-support machine since the accident.']::text[],'[{"sentence":"Is the washing machine working now?","translation":"الان ماشین لباسشویی کار میکنه؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752512.mp3"},{"sentence":"Could you get me a coffee from the drinks machine ?","translation":"آیا می توانید یک قهوه از دستگاه نوشیدنی برای من بیاورید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001990024.mp3"},{"sentence":"The fax machine is broken.","translation":"دستگاه فکس خراب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752513.mp3"},{"sentence":"Turn the machine off before removing the cover.","translation":"قبل از برداشتن درپوش دستگاه را خاموش کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752520.mp3"},{"sentence":"The letters are sorted by machine.","translation":"حروف بر اساس ماشین مرتب شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752523.mp3"},{"sentence":"Did you put my dirty shirts in the machine (= washing machine ) ?","translation":"آیا پیراهن های کثیف مرا در ماشین (= ماشین لباسشویی) گذاشتی؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001990031.mp3"},{"sentence":"I left a message for you on your machine (= telephone answering machine ) .","translation":"در دستگاه شما (= منشی تلفنی) برای شما پیام گذاشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001990035.mp3"},{"sentence":"The machine wouldn’t let me have any money (= cash machine ) .","translation":"دستگاه به من اجازه نمی دهد پولی داشته باشم (= دستگاه پول نقد).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001990039.mp3"}]'::jsonb,8),
('29409c5e-3ae2-5d57-9f7a-01fa0565cafd','c5aea3a9-cf41-513d-8c5b-0a394ea8fab7',2,null,null,'spoken & written','a computer',null,null,'یک کامپیوتر','{}'::text[],'{}'::text[],array['switch on/turn on a machine Turn the machine on and slowly add the hot liquid.','switch off/turn off a machine Is the tape machine switched off?','operate/work a machine Have you been taught to operate the machine properly?','use a machine Can you use the copy machine?','a machine operates/works The machine works using solar power.','install a machine (= put it somewhere and connect it so it can be used ) 300 new machines have been installed across the country.','upgrade a machine (= add new and better parts to it or replace it with a better one ) How much will it cost to upgrade the machine?','a washing machine (= for washing clothes ) Put your dirty clothes straight in the washing machine.','a sewing machine Can I borrow your sewing machine to make some curtains?','an answering machine (= for recording telephone messages ) There’s a message on the answering machine.','a coffee machine (= for providing cups of coffee ) She was at the coffee machine last time I saw her.','a vending machine (= for supplying drinks, chocolate bars etc ) You can buy hot drinks from the vending machine in the corridor.','a cash/ATM machine (= for giving you money from your bank account ) I need to stop at a cash machine.','a slot machine (= for putting coins in in order to try and win more money ) The casino has 500 slot machines.','a life-support machine (= for keeping a very sick person alive ) He has been on a life-support machine since the accident.']::text[],'[{"sentence":"My machine’s just crashed.","translation":"دستگاه من به تازگی خراب شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752524.mp3"}]'::jsonb,1),
