('310d5de4-13fe-52b1-9c13-2c7f9494f42e','2c7ffc53-b1f4-58e1-9326-be50464dffdd',1,null,null,'spoken & written','someone whose job is to manage part or all of a company or other organization',null,'line manager','مدیر، رئیس (بخش)؛ مدیر (فوتبال)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s now assistant marketing manager for the southeast area.","translation":"او اکنون دستیار مدیر بازاریابی برای منطقه جنوب شرقی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00573.mp3"},{"sentence":"one of our regional managers","translation":"یکی از مدیران منطقه ما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000182449.mp3"},{"sentence":"the general manager of Chevrolet","translation":"مدیر کل شورلت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000182448.mp3"},{"sentence":"a middle manager in a computer company (= someone who manages a small part of a company )","translation":"یک مدیر میانی در یک شرکت کامپیوتری (= کسی که بخش کوچکی از یک شرکت را مدیریت می کند)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817355.mp3"}]'::jsonb,4),
