('5f16f722-06d2-5487-8a18-885f12e16be6','2c7ffc53-b1f4-58e1-9326-be50464dffdd',3,null,null,'spoken & written','someone who is in charge of the business affairs of a singer , an actor etc',null,null,'کسی که مسئول امور تجاری یک خواننده، یک بازیگر و غیره است','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('f094994a-2903-5a23-b704-dac884d86a13','bf8f8ce8-9f23-5df0-9346-6a7e69518a8d',1,null,null,'spoken & written','having a husband or a wife',null,null,'متأهل، ازدواج‌کرده؛ (فرد) متأهل','{}'::text[],'{}'::text[],array['be married She’s married now, and living in London.','get married (= to have a wedding ) Did you know that they are going to get married?','stay married I cannot stay married to a man I do not love.','be married with children (= to be married and have children ) Kevin is married with four children.','happily married (= in a happy relationship with your husband or wife ) I have been happily married for nine years.','unhappily married (= not in a happy relationship with your husband or wife ) They were behaving like an unhappily married old couple.','newly/recently married (= married not long ago ) The newly married couple arrived at their hotel.','a married man/woman By 1957 a third of married women were working.','a married couple Most of their friends are married couples.','married life Throughout her married life, her husband’s interests had come first.','somebody’s married name (= a woman’s last name, when she has changed it to her husband’s name ) She gave them Pat’s married name and address.','married quarters (= where soldiers live with their wives ) Can a soldier’s wife continue to live in married quarters if her husband leaves her?']::text[],'[{"sentence":"Are you married or single?","translation":"متاهل هستی یا مجرد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000187099.mp3"},{"sentence":"They’ve been married for eight years.","translation":"آنها هشت سال است که ازدواج کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000187100.mp3"},{"sentence":"Married men earn 70 percent more than single men.","translation":"درآمد مردان متاهل 70 درصد بیشتر از مردان مجرد است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000187101.mp3"},{"sentence":"Nicole is married to my brother.","translation":"نیکول با برادرم ازدواج کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572030.mp3"},{"sentence":"We’re getting married (= marrying ) next month.","translation":"ماه آینده ازدواج می کنیم (= ازدواج می کنیم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572031.mp3"},{"sentence":"a happily married man","translation":"یک مرد متاهل خوشبخت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572035.mp3"},{"sentence":"When she first came to London, she was newly married and out of work.","translation":"وقتی برای اولین بار به لندن آمد، تازه ازدواج کرده و بیکار بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572039.mp3"},{"sentence":"So, how do you like married life ?","translation":"بنابراین، چگونه زندگی زناشویی را دوست دارید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572043.mp3"}]'::jsonb,8),
