('18189dc4-1ad8-5f35-93ce-9fb391708e02','0b124850-ea64-5f59-90b7-d65dedeef005',2,null,null,'spoken & written','unusually large, powerful , or damaging',null,null,'به طور غیرعادی بزرگ، قدرتمند یا آسیب رسان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My phone bill was massive last month.","translation":"قبض تلفن من ماه گذشته هنگفت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572291.mp3"},{"sentence":"massive increases in the number of homeless","translation":"افزایش چشمگیر تعداد بی خانمان ها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752351.mp3"},{"sentence":"Club members can get a massive discount of £50.","translation":"اعضای باشگاه می توانند از تخفیف هنگفت 50 پوندی بهره مند شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001752352.mp3"},{"sentence":"He suffered a massive stroke.","translation":"او دچار سکته مغزی شدید شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000189211.mp3"},{"sentence":"I had a massive argument with her.","translation":"دعوای شدیدی با او داشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572296.mp3"}]'::jsonb,5),
('302dbfaf-19ed-58f4-8853-af6696625a19','0b124850-ea64-5f59-90b7-d65dedeef005',3,null,null,'informal','extremely good',null,null,'فوق العاده خوب','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Listen to this. It’s a massive song.","translation":"اینو گوش کن این یک آهنگ عظیم است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001808024.mp3"}]'::jsonb,1),
('55ee8fb9-eb87-5c38-b698-b31d03876525','3a4f2477-4320-58b0-8f61-8cc514610e17',1,null,null,'spoken & written','the maximum amount , quantity , speed etc is the largest that is possible or allowed',null,null,'حداکثر، بیشینه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The car has a maximum speed of 120 mph.","translation":"حداکثر سرعت این خودرو 120 مایل در ساعت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000214071.mp3"},{"sentence":"They made maximum use of the resources available.","translation":"از منابع موجود حداکثر استفاده را کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000214073.mp3"},{"sentence":"To get the maximum benefit, do the exercises slowly.","translation":"برای به دست آوردن حداکثر سود، تمرینات را به آرامی انجام دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572741.mp3"},{"sentence":"Display the hologram under a strong light for maximum effect.","translation":"هولوگرام را زیر نور قوی برای حداکثر اثر نمایش دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817172.mp3"},{"sentence":"The plant is operating at maximum capacity .","translation":"کارخانه با حداکثر ظرفیت کار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572742.mp3"},{"sentence":"Work out the maximum amount you can afford to spend.","translation":"حداکثر مبلغی را که می توانید خرج کنید، تعیین کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001757618.mp3"},{"sentence":"The award will consist of a lump sum to a maximum value of $5,000.","translation":"این جایزه شامل مبلغ یکجا تا حداکثر 5000 دلار خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001757619.mp3"},{"sentence":"She faces a maximum penalty of life in prison.","translation":"او با حداکثر مجازات حبس ابد روبرو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572750.mp3"}]'::jsonb,8),
('4c84e812-5f15-50ef-bd41-bd1eb1f48c02','7a3167a4-0a08-5a35-8cb3-c06227e36d60',1,null,null,'spoken & written','the largest number or amount that is possible or is allowed',null,null,'بیشترین تعداد یا مقداری که ممکن یا مجاز است',array['minimum']::text[],'{}'::text[],array['an absolute maximum Entries are limited to an absolute maximum of 100 words.','the statutory/legal maximum (= one set by law ) The legal maximum for election contributions was $1,000.','the agreed/stipulated/recommended maximum (= one that is agreed between people ) A pregnant woman should drink no more than the recommended maximum of 4 units per week.','have a maximum Each submarine will have a maximum of 128 warheads.','reach a maximum These sheep reach a maximum of 70 kg at adulthood.','exceed a maximum The fine must not exceed the statutory maximum.','limit/restrict to a maximum The amount you will have to pay is limited to 10% of the total.','allow a maximum To lose weight, allow yourself only 1,500 calories per day.']::text[],'[{"sentence":"He faces a maximum of seven years in prison.","translation":"او با حداکثر هفت سال زندان مواجه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572751.mp3"},{"sentence":"The company will reimburse you up to a maximum of $1,000.","translation":"این شرکت حداکثر تا 1000 دلار به شما بازپرداخت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572752.mp3"},{"sentence":"We might have a third child, but that’s the absolute maximum .","translation":"ما ممکن است فرزند سوم داشته باشیم، اما این حداکثر مطلق است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572756.mp3"}]'::jsonb,3),
('c73555b7-4de4-5f62-a6fb-e72bc079f347','611c5c67-27eb-59f4-80eb-50e182df38ca',1,'of a word/sign etc','از یک کلمه / علامت و غیره','spoken & written','the thing or idea that a word , expression , or sign represents','[ countable, uncountable ]',null,'معنا، مفهوم؛ مقصود؛ هدف (زندگی)','{}'::text[],'{}'::text[],array['have a meaning The same word may have several different meanings.','take on a meaning (= begin to have a new meaning ) The word ‘chaos’ has taken on a special scientific meaning.','understand the meaning The pictures help the children understand the meanings of the words.','know the meaning Do you know the meaning of the word ‘paraphrase’?','get somebody’s meaning ( also take somebody’s meaning British English ) (= understand what someone is saying in an indirect way ) He’s not like other people, if you get my meaning.','grasp the meaning (= begin to understand the meaning ) She suddenly grasped the meaning of his frantic gestures.','carry meaning ( also bear a meaning formal ) (= have a meaning ) In conversation, even a pause may carry meaning.','convey meaning (= express a meaning ) the use of hand signals to convey meaning','precise/specific/exact The term ‘stress’ has a precise meaning to an engineer.','a hidden meaning She felt there was a hidden meaning behind his words.','a double meaning (= two meanings at the same time ) Everything he said had a double meaning.','the literal meaning The literal meaning of ‘telephone’ is ‘far-away sound’.','the ordinary meaning They are a ''nuisance'' in the ordinary meaning, not the legal meaning, of that word.','the figurative/metaphorical meaning (= different from its usual or basic meaning ) The expression has a metaphorical meaning.','somebody’s/something’s true meaning Children understand the true meaning of these words.','a symbolic meaning (= representing an idea ) Colours often have symbolic meanings; for example, black signifies grief in Western cultures.']::text[],'[{"sentence":"I don’t know the precise meaning of the word ‘gleaned’.","translation":"من معنی دقیق کلمه \"چندیده\" را نمی دانم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216215.mp3"}]'::jsonb,1),
('f88ae53c-213a-5e6b-a5de-ff5bdba79207','611c5c67-27eb-59f4-80eb-50e182df38ca',2,'ideas in speech/book etc','ایده ها در گفتار/کتاب و غیره','spoken & written','the thoughts or ideas that someone wants you to understand from what they say, do, write etc','[ countable, uncountable ]',null,'افکار یا ایده هایی که کسی می خواهد شما را از آنچه می گوید، انجام می دهد، می نویسد و غیره می فهمد','{}'::text[],'{}'::text[],array['have a meaning The same word may have several different meanings.','take on a meaning (= begin to have a new meaning ) The word ‘chaos’ has taken on a special scientific meaning.','understand the meaning The pictures help the children understand the meanings of the words.','know the meaning Do you know the meaning of the word ‘paraphrase’?','get somebody’s meaning ( also take somebody’s meaning British English ) (= understand what someone is saying in an indirect way ) He’s not like other people, if you get my meaning.','grasp the meaning (= begin to understand the meaning ) She suddenly grasped the meaning of his frantic gestures.','carry meaning ( also bear a meaning formal ) (= have a meaning ) In conversation, even a pause may carry meaning.','convey meaning (= express a meaning ) the use of hand signals to convey meaning','precise/specific/exact The term ‘stress’ has a precise meaning to an engineer.','a hidden meaning She felt there was a hidden meaning behind his words.','a double meaning (= two meanings at the same time ) Everything he said had a double meaning.','the literal meaning The literal meaning of ‘telephone’ is ‘far-away sound’.','the ordinary meaning They are a ''nuisance'' in the ordinary meaning, not the legal meaning, of that word.','the figurative/metaphorical meaning (= different from its usual or basic meaning ) The expression has a metaphorical meaning.','somebody’s/something’s true meaning Children understand the true meaning of these words.','a symbolic meaning (= representing an idea ) Colours often have symbolic meanings; for example, black signifies grief in Western cultures.']::text[],'[{"sentence":"The meaning of her words was clear. We’d lost our jobs.","translation":"معنی حرفش واضح بود. ما کارمان را از دست داده بودیم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216224.mp3"},{"sentence":"She hardly dared to understand the meaning behind his statement.","translation":"او به سختی جرات درک معنای پشت گفته او را داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001734134.mp3"}]'::jsonb,2),
('db1c6f44-36cc-5ae2-b66d-29fd96289cc8','611c5c67-27eb-59f4-80eb-50e182df38ca',3,null,null,'spoken & written',null,null,'what’s the meaning of this?','معنا، مفهوم؛ مقصود؛ هدف (زندگی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('2010d42e-7e91-5be3-8727-c9c417f77a9e','611c5c67-27eb-59f4-80eb-50e182df38ca',4,'purpose/special quality','هدف/کیفیت ویژه','spoken & written','the quality that makes life, work etc seem to have a purpose or value','[ uncountable ]',null,'کیفیتی که باعث می شود زندگی، کار و غیره هدف یا ارزشی داشته باشند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Life seemed to have lost its meaning since Janet’s death.","translation":"به نظر می رسید زندگی از زمان مرگ جانت معنای خود را از دست داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216248.mp3"},{"sentence":"Her studies no longer seemed to have any meaning .","translation":"مطالعات او دیگر معنایی نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216251.mp3"},{"sentence":"For many people it is religion that gives meaning to their existence.","translation":"برای بسیاری از مردم این دین است که به وجود آنها معنا می بخشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001734145.mp3"}]'::jsonb,3),
('65044b57-8b70-5b9c-aa45-5176262599cf','611c5c67-27eb-59f4-80eb-50e182df38ca',5,'true nature','طبیعت واقعی','spoken & written','the true nature and importance of something','[ uncountable ]',null,'ماهیت و اهمیت واقعی چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We seem to have forgotten the true meaning of Christmas.","translation":"به نظر می رسد ما معنای واقعی کریسمس را فراموش کرده ایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001734151.mp3"}]'::jsonb,1),
('6f60375c-1344-5683-9139-36fd32df8d6a','611c5c67-27eb-59f4-80eb-50e182df38ca',6,null,null,'spoken & written',null,null,'(not) know the meaning of something','معنا، مفهوم؛ مقصود؛ هدف (زندگی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('125c5780-5c18-542c-82b5-d4aba5973aa1','09670c75-1629-5156-b2ee-4e4e79f5139e',1,null,null,'spoken & written','to find the size , length , or amount of something, using standard units such as inch es , metres etc','[ transitive ]',null,'اندازه‌گیری کردن؛ سنجیدن؛ محاسبه کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The rainfall was measured over a three-month period.","translation":"میزان بارندگی در یک دوره سه ماهه اندازه گیری شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216704.mp3"},{"sentence":"She was being measured for her wedding dress.","translation":"او را برای لباس عروسش اندازه می گرفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216708.mp3"},{"sentence":"We can measure the energy that food provides in calories.","translation":"ما می‌توانیم انرژی غذا را به صورت کالری اندازه‌گیری کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766784.mp3"}]'::jsonb,3),
('203668fa-4bfb-5600-8219-ad8b349d1068','09670c75-1629-5156-b2ee-4e4e79f5139e',2,null,null,'spoken & written','to judge the importance , value, or true nature of something','[ transitive ]',null,'قضاوت درباره اهمیت، ارزش یا ماهیت واقعی چیزی',array['assess']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Doctors say it is too early to measure the effectiveness of the drug.","translation":"پزشکان می گویند هنوز برای اندازه گیری اثربخشی دارو زود است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714672.mp3"},{"sentence":"Education shouldn’t be measured purely by examination results.","translation":"تحصیلات را نباید صرفاً با نتایج امتحان سنجید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766787.mp3"}]'::jsonb,2),
('10192a2d-e6a9-582b-adf1-4f50b9ded3eb','09670c75-1629-5156-b2ee-4e4e79f5139e',3,null,null,'spoken & written','to be a particular size, length, or amount','[ linking verb ]',null,'اندازه، طول یا مقدار خاصی باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The room measures 6 x 6 metres.","translation":"ابعاد اتاق 6×6 متر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714676.mp3"},{"sentence":"The earthquake measured 6.5 on the Richter scale.","translation":"قدرت این زمین لرزه 6.5 در مقیاس ریشتر بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216723.mp3"}]'::jsonb,2),
('54a6de8c-d189-5244-88d5-ee6e5d95fb80','09670c75-1629-5156-b2ee-4e4e79f5139e',4,null,null,'spoken & written','if a piece of equipment measures something, it shows or records a particular kind of measurement','[ transitive ]',null,'اگر یک قطعه از تجهیزات چیزی را اندازه گیری کند، نوع خاصی از اندازه گیری را نشان می دهد یا ثبت می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"An odometer measures the number of miles your car travels.","translation":"کیلومتر شمار تعداد مایل هایی که ماشین شما طی می کند را اندازه گیری می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000216728.mp3"}]'::jsonb,1),
('c7c98ee1-49ac-5d74-b865-00e10e9b4f44','a2bd3b45-619a-50c1-bcd6-935cc8158ca7',1,'action','اقدام','spoken & written','an action, especially an official one, that is intended to deal with a particular problem',null,null,'اقدام، تدبیر؛ اندازه‌گیری؛ واحد اندازه',array['step']::text[],'{}'::text[],array['take measures (= do something in order to deal with a problem ) We are taking measures to improve the situation.','adopt/introduce a measure (= start using a particular way of dealing with a problem ) The countries agreed to adopt measures to reduce pollution.','a measure is aimed at doing something The measures were aimed at reducing the speed of cars on the roads.','a safety measure New safety measures were implemented after the rail crash.','a security measure (= something done to keep a place safe from danger or crime ) Video surveillance cameras have been installed as a security measure.','a preventative/precautionary measure (= something done to prevent something bad ) Vaccination against disease is a sensible preventative measure.','a extreme measure The public would not be in favour of such an extreme measure.','a drastic measure (= an extreme measure ) Drastic measures are needed if we are to combat global warming.','a temporary measure (= something done for a limited period of time to deal with a problem ) The tents were used as a temporary measure to replace homes destroyed in the floods.','a necessary measure The army will take all necessary measures to protect the public.','an appropriate measure (= a measure that is suitable for a particular situation ) In the event of an assault, staff will need to take appropriate measures to defend themselves.','a package/series of measures (= a set of measures used to deal with something ) A package of road safety measures has been announced.']::text[],'[{"sentence":"Measures are being taken to reduce crime in the city.","translation":"اقداماتی برای کاهش جرم و جنایت در این شهرستان انجام می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714616.mp3"},{"sentence":"drastic measures to reduce traffic problems","translation":"اقدامات جدی برای کاهش مشکلات ترافیکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001817208.mp3"},{"sentence":"New safety measures were being demanded after last night’s horrific train crash.","translation":"پس از تصادف وحشتناک قطار دیشب، اقدامات ایمنی جدیدی درخواست شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714624.mp3"},{"sentence":"The new bridge was erected as a temporary measure to replace the one which was destroyed by floods.","translation":"پل جدید به عنوان اقدامی موقت برای جایگزینی پل که در اثر سیل ویران شده بود ساخته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714628.mp3"},{"sentence":"He was kept in hospital overnight as a precautionary measure.","translation":"او به عنوان یک اقدام احتیاطی یک شب در بیمارستان بستری شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001714635.mp3"}]'::jsonb,5),
('aec67bad-934b-5fd7-ad1d-fdce06907a50','a2bd3b45-619a-50c1-bcd6-935cc8158ca7',2,null,null,'spoken & written',null,null,'half measures','اقدام، تدبیر؛ اندازه‌گیری؛ واحد اندازه','{}'::text[],'{}'::text[],array['take measures (= do something in order to deal with a problem ) We are taking measures to improve the situation.','adopt/introduce a measure (= start using a particular way of dealing with a problem ) The countries agreed to adopt measures to reduce pollution.','a measure is aimed at doing something The measures were aimed at reducing the speed of cars on the roads.','a safety measure New safety measures were implemented after the rail crash.','a security measure (= something done to keep a place safe from danger or crime ) Video surveillance cameras have been installed as a security measure.','a preventative/precautionary measure (= something done to prevent something bad ) Vaccination against disease is a sensible preventative measure.','a extreme measure The public would not be in favour of such an extreme measure.','a drastic measure (= an extreme measure ) Drastic measures are needed if we are to combat global warming.','a temporary measure (= something done for a limited period of time to deal with a problem ) The tents were used as a temporary measure to replace homes destroyed in the floods.','a necessary measure The army will take all necessary measures to protect the public.','an appropriate measure (= a measure that is suitable for a particular situation ) In the event of an assault, staff will need to take appropriate measures to defend themselves.','a package/series of measures (= a set of measures used to deal with something ) A package of road safety measures has been announced.']::text[],'[]'::jsonb,0),
