('221e70ef-9bda-53a5-a19e-1a5870c34576','e97225f9-c50d-50d2-9dc9-5c3af6b04295',1,null,null,'spoken & written','to understand something wrongly',null,null,'چیزی را اشتباه فهمیدن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She mistook my meaning entirely.","translation":"او معنای من را کاملا اشتباه گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000203008.mp3"},{"sentence":"Ken mistook her concern, thinking she was interested in him for another reason.","translation":"کن نگرانی او را اشتباه گرفت و فکر کرد که به دلیل دیگری به او علاقه مند است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000203007.mp3"}]'::jsonb,2),
