('5be16f37-0228-540d-aa9e-aece8e600335','2377ebfa-6149-5e77-ac91-d5df8092b61b',1,null,null,'spoken & written','used to greet someone in the morning',null,null,'صبح به کسی سلام می کرد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Morning, everybody!","translation":"صبح، همه!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040147.mp3"}]'::jsonb,1),
('b52c3216-f8b6-5d92-9ec0-9fde2d9c641b','cf7536be-3597-5a23-8074-6f6cca0a09d8',1,null,null,'spoken & written','relating to music or consisting of music','[ only before noun ]',null,'موسیقایی، نغمه‌دار؛ موزیکال (نمایش)؛ استعداد (موسیقی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a musical version of the fairy tale ‘Cinderella’","translation":"نسخه موزیکال داستان پریان \"سیندرلا\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000197400.mp3"},{"sentence":"When he began his musical career, King played only for black audiences.","translation":"زمانی که کینگ فعالیت موسیقی خود را آغاز کرد، فقط برای تماشاگران سیاه پوست می نواخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000197399.mp3"}]'::jsonb,2),
('4fcb0805-8987-53e5-9138-cf16cc6cba02','cf7536be-3597-5a23-8074-6f6cca0a09d8',2,null,null,'spoken & written','good at or interested in playing or singing music',null,null,'به نواختن یا آواز خواندن موسیقی خوب یا علاقه مند است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s very musical and loves to sing.","translation":"او بسیار موزیکال است و عاشق خواندن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000197404.mp3"}]'::jsonb,1),
('ff0ef7c0-8365-5433-b7a2-3ddd00045cbe','cf7536be-3597-5a23-8074-6f6cca0a09d8',3,null,null,'spoken & written','having a pleasant sound like music',null,null,'داشتن صدای دلنشین مثل موسیقی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a sweet musical voice","translation":"صدای موسیقی شیرین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000197409.mp3"}]'::jsonb,1),
('0904e421-b9dd-5afd-a466-00ae6a0cbf8b','46cabf26-f044-5c23-be49-65a39d5083c4',1,null,null,'spoken & written','a play or film that includes singing and dancing',null,null,'نمایشنامه یا فیلمی که شامل آواز و رقص است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Webber had three musicals playing in London at one time.","translation":"وبر در یک زمان سه موزیکال در لندن داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000197430.mp3"},{"sentence":"Carroll appeared in a number of Broadway musicals.","translation":"کارول در تعدادی از موزیکال های برادوی ظاهر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001555912.mp3"}]'::jsonb,2),
('5f0a520e-8450-5e85-ba64-319a024e9417','08804f67-54ad-593c-9e56-723d6e773baa',1,null,null,'spoken & written','an event, situation etc that people do not understand or cannot explain because they do not know enough about it','[ countable usually singular ]',null,'راز، معمایی؛ غموض؛ معما (داستان)','{}'::text[],'{}'::text[],array['be a mystery It’s a mystery how he got my phone number.','remain a mystery What caused the accident remains a mystery.','solve/unravel a mystery (= find out what happened ) The children were given the clues and had to try to solve the mystery.','the mystery deepens (= it becomes more difficult to understand ) Why would he run away if he were not guilty? The mystery deepens.','the mystery surrounding something Research has unravelled much of the mystery surrounding the ageing process.','a complete/total mystery She said that her husband’s disappearance was a complete mystery.','an unsolved mystery What happened to her is still an unsolved mystery.','a great mystery (= a big and important mystery ) It is one of the great mysteries of science.','a little/minor mystery It was a minor mystery how the file had survived the fire.','a big mystery If they are right, they have solved one of the biggest mysteries in astronomy.','something is one of life’s (little) mysteries (= it is something that you will never understand – used humorously ) Where socks disappear to after they’ve been washed is one of life’s little mysteries.']::text[],'[{"sentence":"Twenty years after the event, his death remains a mystery .","translation":"بیست سال پس از این رویداد، مرگ او همچنان یک راز باقی مانده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000198631.mp3"},{"sentence":"The way her mind worked was always a mystery to him.","translation":"نحوه کار ذهن او همیشه برای او یک راز بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001974698.mp3"},{"sentence":"‘Why did he do it?’ ‘I don’t know. It’s a complete mystery .’","translation":"«چرا این کار را کرد؟» «نمی‌دانم. این یک راز کامل است.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535306.mp3"},{"sentence":"The police never solved the mystery of Gray’s disappearance.","translation":"پلیس هرگز معمای ناپدید شدن گری را حل نکرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000198635.mp3"},{"sentence":"But why would anyone want to kill Jack? The mystery deepened .","translation":"اما چرا کسی بخواهد جک را بکشد؟ راز عمیق تر شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535316.mp3"},{"sentence":"What happened to the paintings after that is an unsolved mystery .","translation":"بعد از آن چه اتفاقی برای نقاشی ها افتاد یک معمای حل نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535303.mp3"},{"sentence":"I don’t know how he got the job – it’s one of life’s little mysteries .","translation":"نمی‌دانم او چگونه این شغل را به دست آورد - این یکی از رازهای کوچک زندگی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001974712.mp3"},{"sentence":"How life began on Earth is one of the great mysteries of science.","translation":"چگونگی آغاز حیات بر روی زمین یکی از اسرار بزرگ علم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535323.mp3"}]'::jsonb,8),
('f5642c9a-8cef-5fc0-b258-ac78144f043d','08804f67-54ad-593c-9e56-723d6e773baa',2,null,null,'spoken & written','the quality that something or someone has when they seem strange , secret , or difficult to understand or explain','[ uncountable ]',null,'کیفیتی که چیزی یا کسی در زمانی که به نظر عجیب، مخفی یا دشوار به نظر می رسد، دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her dark glasses gave her an air of mystery .","translation":"عینک تیره اش حالتی مرموز به او می داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000198656.mp3"},{"sentence":"Annie knew that there was some mystery surrounding her birth.","translation":"آنی می‌دانست که رازهایی پیرامون تولد او وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535309.mp3"},{"sentence":"The circumstances of his death were veiled in mystery.","translation":"شرایط مرگ او در هاله ای از ابهام قرار داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000198659.mp3"}]'::jsonb,3),
('01e0d00a-c4a6-597b-bb94-87a83627add8','08804f67-54ad-593c-9e56-723d6e773baa',3,null,null,'spoken & written','a subject , activity etc that is very complicated , secret, or difficult to understand, and that people want to learn about','[ countable usually plural ]',null,'یک موضوع، فعالیت و غیره که بسیار پیچیده، مخفیانه، یا درک آن دشوار است و مردم می خواهند درباره آن بیاموزند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"his introduction to the mysteries of the perfume business","translation":"معرفی او به اسرار تجارت عطر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759410.mp3"}]'::jsonb,1),
('04b4bd54-4d40-51d5-985c-f754ec3817a7','08804f67-54ad-593c-9e56-723d6e773baa',4,null,null,'spoken & written','a story, film , or play about a murder , in which you are not told who the murderer is until the end','[ countable ]',null,'یک داستان، فیلم یا نمایشنامه درباره یک قتل که در آن تا آخر به شما گفته نمی شود قاتل کیست.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an Agatha Christie mystery","translation":"راز آگاتا کریستی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001974717.mp3"}]'::jsonb,1),
('cb7d4d67-e6bb-540d-83c1-85515c0dd84a','558d2174-5e73-5643-a8cc-d329d8724c50',1,null,null,'spoken & written','used to describe someone or something that people do not recognize or know anything about, especially when this causes great interest',null,null,'برای توصیف کسی یا چیزی که مردم چیزی در مورد آن نمی‌شناسند یا نمی‌دانند، استفاده می‌شود، به‌ویژه زمانی که این باعث علاقه زیادی شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Who was the mystery woman spotted on board the yacht with the prince?","translation":"زن مرموز که با شاهزاده روی قایق تفریحی دیده شد چه کسی بود؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535375.mp3"},{"sentence":"a mystery virus","translation":"یک ویروس مرموز","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535376.mp3"}]'::jsonb,2),
('208c7966-dce4-5da2-b00c-ba9bf97886f0','eae2777f-49e7-5bda-bb71-81111ed9d72d',1,'nature','طبیعت','spoken & written','existing in nature and not caused, made, or controlled by people',null,null,'طبیعی، بدون مصنوع؛ عادی؛ بی‌قاعده (رفتار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the study of the natural world (= trees, rivers, animals, plants etc )","translation":"مطالعه جهان طبیعی (= درختان، رودخانه ها، حیوانات، گیاهان و غیره)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535553.mp3"},{"sentence":"an area of spectacular natural beauty","translation":"منطقه ای با زیبایی های طبیعی دیدنی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535557.mp3"},{"sentence":"natural disasters (= things such as floods or earthquake s )","translation":"بلایای طبیعی (= چیزهایی مانند سیل یا زلزله)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535560.mp3"},{"sentence":"death from natural causes","translation":"مرگ به دلایل طبیعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535566.mp3"},{"sentence":"the need for natural light in offices","translation":"نیاز به نور طبیعی در ادارات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759744.mp3"}]'::jsonb,5),
('0bdf616a-aa9c-5475-9c28-1e01cc776cd2','eae2777f-49e7-5bda-bb71-81111ed9d72d',2,'normal','عادی','spoken & written','normal and as you would expect',null,null,'عادی و همانطور که انتظار دارید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"At the time, accepting his offer had seemed the most natural thing in the world .","translation":"در آن زمان، پذیرش پیشنهاد او طبیعی ترین چیز در جهان به نظر می رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535569.mp3"},{"sentence":"It’s not natural for a child of his age to be so quiet.","translation":"طبیعی نیست که کودکی در سن خودش اینقدر ساکت باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234316.mp3"},{"sentence":"It’s only natural that he should be interested in what happens.","translation":"طبیعی است که او باید به اتفاقی که می افتد علاقه مند باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816652.mp3"},{"sentence":"It was a perfectly natural (= not surprising ) mistake to make.","translation":"این یک اشتباه کاملاً طبیعی (= تعجب آور نیست) بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816657.mp3"}]'::jsonb,4),
('85e17d60-5ebe-5a79-bb55-0e9e08bf41cc','eae2777f-49e7-5bda-bb71-81111ed9d72d',3,'behaviour','رفتار','spoken & written','a natural tendency or type of behaviour is part of your character when you are born , rather than one that you learn later',null,null,'یک گرایش طبیعی یا نوع رفتار بخشی از شخصیت شما در هنگام تولد است، نه چیزی که بعداً یاد می گیرید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Babies have a natural fear of falling.","translation":"نوزادان ترس طبیعی از افتادن دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535574.mp3"}]'::jsonb,1),
('da93b3ac-13d0-5555-a657-c15f4d4e2dd3','eae2777f-49e7-5bda-bb71-81111ed9d72d',4,'ability','توانایی','spoken & written','having a particular quality or skill without needing to be taught and without needing to try hard',null,null,'داشتن یک کیفیت یا مهارت خاص بدون نیاز به آموزش و بدون نیاز به تلاش زیاد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a natural musician","translation":"یک نوازنده طبیعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535580.mp3"},{"sentence":"Cheryl has a natural elegance about her.","translation":"شریل در مورد او ظرافت طبیعی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535581.mp3"},{"sentence":"his natural ability with figures","translation":"توانایی طبیعی او با فیگورها","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535582.mp3"}]'::jsonb,3),
('56a8e99d-8aaa-58ef-aa47-66b374b5c71f','eae2777f-49e7-5bda-bb71-81111ed9d72d',5,'relaxed','آرام','spoken & written','behaving in a way that is normal and shows you are relaxed and not trying to pretend',null,null,'به گونه ای رفتار کنید که طبیعی است و نشان می دهد شما آرام هستید و سعی در تظاهر ندارید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Be cool, be natural.","translation":"خونسرد باشید، طبیعی باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234354.mp3"}]'::jsonb,1),
('af63d6b6-476c-51da-86a4-702a19c3404e','eae2777f-49e7-5bda-bb71-81111ed9d72d',6,'parent/child','والد / فرزند','old-fashioned','someone’s natural parent or child is their real parent or child, who is biologically related to them','[ only before noun ]',null,'والد یا فرزند طبیعی یک فرد، والد یا فرزند واقعی اوست که از نظر بیولوژیکی با او مرتبط است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"An adopted young person has the right to trace his natural parents.","translation":"یک جوان فرزندخوانده حق دارد از والدین طبیعی خود ردیابی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000234360.mp3"},{"sentence":"He was rumoured to be the natural son of a duke.","translation":"شایعه شده بود که او پسر طبیعی یک دوک است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759755.mp3"}]'::jsonb,2),
