('441b784f-4103-55e4-8d7c-f091881e70ba','bff1de58-d15a-50e7-bbc0-c09938dd846f',1,null,null,'spoken & written','not one or the other of two people or things',null,null,'هیچ‌کدام (از دو)، نه یکی نه دیگری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Would you like tea or coffee?’ ‘Neither, thanks.’","translation":"«چای می‌خواهی یا قهوه؟» «نه، متشکرم.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712376.mp3"},{"sentence":"It was a game in which neither team deserved to win.","translation":"بازی ای بود که هیچ کدام از تیم ها مستحق برد نبودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712375.mp3"},{"sentence":"Neither of them can cook.","translation":"هیچ کدام از آنها نمی توانند آشپزی کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712379.mp3"},{"sentence":"Thompson had two strategies, neither of which seems to have worked very well.","translation":"تامپسون دو استراتژی داشت که به نظر می رسد هیچ کدام از آنها خیلی خوب عمل نکرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712380.mp3"},{"sentence":"We asked both John and Jerry, but neither one could offer a satisfactory explanation.","translation":"ما از جان و جری پرسیدیم، اما هیچ‌کدام نتوانستند توضیح رضایت‌بخشی ارائه دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001821407.mp3"}]'::jsonb,5),
('8b8e7757-bc48-5b39-b67f-d87fed278305','c5a6ea26-4c05-590b-81e2-3003f6a3635c',1,null,null,'spoken & written','used to show that a negative statement is also true about another person or thing',null,null,'نه او هم؛ همچنین نه (نفی دوم)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘I don’t have any money.’ ‘Neither do I.’","translation":"«من هیچ پولی ندارم.» «من هم ندارم.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238989.mp3"},{"sentence":"Tom didn’t believe a word she said, and neither did the police.","translation":"تام حتی یک کلمه او را باور نکرد و پلیس هم باور نکرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238990.mp3"},{"sentence":"‘I don’t like horror movies.’ ‘ Me neither .’","translation":"\"من فیلم های ترسناک را دوست ندارم.\" \"من نه.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238993.mp3"}]'::jsonb,3),
