('8708756f-095e-5051-8966-f7d15569cf38','a6bf57dc-6d13-582d-8e45-cf2be3430c70',4,null,null,'formal','used to add another negative statement about someone or something',null,null,'برای اضافه کردن یک جمله منفی دیگر در مورد کسی یا چیزی استفاده می شود',array['nor']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The authorities were not sympathetic to the students’ demands, neither would they tolerate any disruption.","translation":"مقامات با خواسته های دانشجویان همدل نبودند و هیچ گونه اختلالی را هم تحمل نمی کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712397.mp3"}]'::jsonb,1),
('4fbea0e4-e1e5-5807-bc39-5926a7ef48c1','a6e2f3df-5c0e-5e5e-bc27-ea3ffdb8be9a',1,null,null,'spoken & written','worried or frightened about something, and unable to relax',null,null,'مضطرب، دلواپس؛ عصبی (سازمان)؛ پرشور (پاسخ)','{}'::text[],'{}'::text[],array['feel nervous He looked at her for so long that she began to feel nervous.','get/become nervous Everyone gets nervous before a big game.','seem/appear nervous She seemed nervous at first, but her presentation was good.','look/sound nervous He sounded nervous and uncertain.','make somebody nervous Being alone in the house made her nervous.','slightly nervous Looking slightly nervous, Paul began to speak.','a little/a bit nervous I was a little nervous before the interview.','extremely nervous The policeman noticed that the driver seemed extremely nervous.','a nervous smile/laugh/giggle ‘It doesn’t matter, ’ she said, with a nervous smile.','nervous laughter His comment was met with nervous laughter.','a nervous look/glance Lucy swallowed as she sent him a nervous glance.','nervous tension (= a feeling of being very tense and nervous ) It was the play’s opening night, and Gloria was in a state of nervous tension.','be a nervous wreck (= be so nervous or worried that you cannot deal with a situation ) By the end of the rehearsal I was a nervous wreck.']::text[],'[{"sentence":"She was so nervous about her exams that she couldn’t sleep.","translation":"آنقدر در امتحاناتش عصبی بود که نمی توانست بخوابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000239425.mp3"},{"sentence":"I wish you’d stop looking at me like that. You’re making me nervous .","translation":"کاش اینطوری به من نگاه نمیکردی داری عصبیم میکنی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712522.mp3"},{"sentence":"Paul always gets nervous whenever he has to give a presentation.","translation":"پل همیشه هر زمان که باید ارائه دهد عصبی می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712528.mp3"},{"sentence":"‘Don’t be silly, ’ she said with a nervous laugh. ‘There’s no such thing as ghosts.’","translation":"با خنده ای عصبی گفت: احمق نباش. \"چیزی به نام ارواح وجود ندارد.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712531.mp3"},{"sentence":"By the time I got into the interview I was a nervous wreck (= was extremely nervous ) .","translation":"زمانی که وارد مصاحبه شدم، عصبی بودم (= بسیار عصبی بودم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712532.mp3"},{"sentence":"We were all a bit nervous of him at first (= frightened of him ) .","translation":"همه ما در ابتدا کمی از او عصبی بودیم (= از او می ترسیدیم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712539.mp3"}]'::jsonb,6),
('597d2c44-a87c-5933-98bf-4fb720439d0b','a6e2f3df-5c0e-5e5e-bc27-ea3ffdb8be9a',2,null,null,'spoken & written','often becoming worried or frightened, and easily upset',null,null,'اغلب نگران یا ترسیده می شوند و به راحتی ناراحت می شوند','{}'::text[],'{}'::text[],array['feel nervous He looked at her for so long that she began to feel nervous.','get/become nervous Everyone gets nervous before a big game.','seem/appear nervous She seemed nervous at first, but her presentation was good.','look/sound nervous He sounded nervous and uncertain.','make somebody nervous Being alone in the house made her nervous.','slightly nervous Looking slightly nervous, Paul began to speak.','a little/a bit nervous I was a little nervous before the interview.','extremely nervous The policeman noticed that the driver seemed extremely nervous.','a nervous smile/laugh/giggle ‘It doesn’t matter, ’ she said, with a nervous smile.','nervous laughter His comment was met with nervous laughter.','a nervous look/glance Lucy swallowed as she sent him a nervous glance.','nervous tension (= a feeling of being very tense and nervous ) It was the play’s opening night, and Gloria was in a state of nervous tension.','be a nervous wreck (= be so nervous or worried that you cannot deal with a situation ) By the end of the rehearsal I was a nervous wreck.']::text[],'[{"sentence":"She’s a nervous, sensitive child.","translation":"او یک کودک عصبی و حساس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712543.mp3"},{"sentence":"The film is unsuitable for people of a nervous disposition (= who are easily frightened ) .","translation":"این فیلم برای افراد عصبی (= که به راحتی می ترسند) مناسب نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712544.mp3"}]'::jsonb,2),
