('6f213313-11a2-5f44-9f4a-d4c950f85ec5','907b8e1b-5295-55b4-bde0-204e8f4c5b65',1,null,null,'spoken & written','not anything or no thing',null,null,'هیچ‌چیز، هیچ (نفی)؛ چیز (نه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Nothing ever happens in this town.","translation":"در این شهر هیچ اتفاقی نمی افتد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764470.mp3"},{"sentence":"There’s nothing in this box.","translation":"در این جعبه چیزی نیست","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000247669.mp3"},{"sentence":"There was nothing else the doctors could do.","translation":"دکترها کار دیگری نمی توانستند بکنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572900.mp3"},{"sentence":"He had nothing more to say.","translation":"او دیگر چیزی برای گفتن نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572892.mp3"},{"sentence":"We know nothing about her family.","translation":"ما از خانواده او چیزی نمی دانیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572920.mp3"},{"sentence":"I couldn’t just stand by and do nothing .","translation":"نمی‌توانستم کنار بایستم و کاری نکنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001964475.mp3"},{"sentence":"I promised to say nothing about it to anyone.","translation":"قول دادم در این مورد به کسی چیزی نگویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001964479.mp3"},{"sentence":"We’ve heard nothing from her for weeks.","translation":"هفته هاست که از او چیزی نشنیده ایم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001964483.mp3"},{"sentence":"There’s absolutely nothing to be ashamed of.","translation":"مطلقاً چیزی برای خجالت وجود ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572896.mp3"},{"sentence":"‘Do you know much about business?’ ‘ Nothing at all .’","translation":"«آیا چیز زیادی در مورد تجارت می‌دانی؟» «اصلاً هیچی.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572908.mp3"},{"sentence":"She had eaten virtually nothing at supper.","translation":"او تقریباً هیچ چیزی در شام نخورده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572907.mp3"},{"sentence":"There’s nothing wrong with the data.","translation":"هیچ مشکلی با داده ها وجود ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572912.mp3"},{"sentence":"There’s nothing new about this.","translation":"هیچ چیز جدیدی در این مورد وجود ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001572916.mp3"},{"sentence":"A brief search was made but they found nothing untoward .","translation":"جست و جوی مختصری انجام شد اما هیچ چیز ناخوشایندی پیدا نکردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816946.mp3"}]'::jsonb,14),
