('27c2c044-6838-5448-aef2-b38d4ed2cd05','dcffaeaa-6e08-57e8-8432-cba7fb2fd088',2,null,null,'spoken & written','relating to or involving the use of weapons that use nuclear energy',null,null,'مربوط به یا شامل استفاده از سلاح هایی که از انرژی هسته ای استفاده می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the threat of nuclear attack","translation":"تهدید حمله هسته ای","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000249304.mp3"},{"sentence":"concern about the country’s nuclear weapons program","translation":"نگرانی در مورد برنامه تسلیحات هسته ای این کشور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573397.mp3"},{"sentence":"With the collapse of the former Soviet Union, the possibility of a nuclear holocaust (= a nuclear war that destroys much of the Earth ) was greatly reduced.","translation":"با فروپاشی اتحاد جماهیر شوروی سابق، احتمال هولوکاست هسته ای (= جنگ هسته ای که بخش زیادی از زمین را ویران می کند) بسیار کاهش یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573392.mp3"},{"sentence":"a nuclear testing area","translation":"یک منطقه آزمایش هسته ای","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001573400.mp3"}]'::jsonb,4),
('17b0dfa5-b464-556c-8b92-63e1e51e53a0','ff9cf72e-efb6-5a47-a64b-d918678877a4',1,null,null,'formal','to see and notice something','[ transitive not in progressive ]',null,'مشاهده کردن؛ رعایت کردن (قانون)؛ جشن گرفتن (تأیید)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Scientists have observed a drop in ozone levels over the Antarctic.","translation":"دانشمندان کاهش سطح ازن را بر فراز قطب جنوب مشاهده کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557540.mp3"},{"sentence":"It was observed that 40 percent of patients had high blood pressure.","translation":"مشاهده شد که 40 درصد بیماران فشار خون بالا داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257384.mp3"},{"sentence":"Officers observed him driving at 90 miles per hour.","translation":"مأموران او را در حال رانندگی با سرعت 90 مایل در ساعت مشاهده کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257381.mp3"},{"sentence":"Predators have been observed to avoid attacking brightly coloured species.","translation":"مشاهده شده است که شکارچیان از حمله به گونه های رنگارنگ اجتناب می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001760027.mp3"},{"sentence":"She was spotted going into a restaurant with a well-known footballer.","translation":"او در حال رفتن به یک رستوران با یک فوتبالیست سرشناس دیده شد.","audio_url":null}]'::jsonb,5),
('27b0b76e-01c0-523e-bcfa-580e6bdf9e6c','ff9cf72e-efb6-5a47-a64b-d918678877a4',2,null,null,'spoken & written','to watch something or someone carefully','[ intransitive, transitive ]',null,'به دقت تماشا کردن چیزی یا کسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The police have been observing his movements.","translation":"پلیس حرکات او را زیر نظر دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257391.mp3"},{"sentence":"One student performs the experiment, while his partner observes.","translation":"یکی از دانش آموزان آزمایش را انجام می دهد، در حالی که شریک زندگی او مشاهده می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557544.mp3"},{"sentence":"Observe how the people in the group interact.","translation":"نحوه تعامل افراد گروه را مشاهده کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257394.mp3"}]'::jsonb,3),
('8f1e4b45-46bf-5717-ba34-93ec3ca79a82','ff9cf72e-efb6-5a47-a64b-d918678877a4',3,null,null,'formal','to say or write what you have noticed about a situation','[ transitive ]',null,'برای گفتن یا نوشتن آنچه در مورد یک موقعیت متوجه شده اید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Sid looks ill, ’ Doherty observed.","translation":"دوهرتی مشاهده کرد: «سید بیمار به نظر می رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257406.mp3"},{"sentence":"Keynes observed that humans fall into two classes.","translation":"کینز مشاهده کرد که انسان ها به دو دسته تقسیم می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257409.mp3"}]'::jsonb,2),
('8aeb8831-530a-50c5-938d-337e8a231af3','ff9cf72e-efb6-5a47-a64b-d918678877a4',4,null,null,'spoken & written','to do what you are supposed to do according to a law or agreement','[ transitive ]',null,'برای انجام کاری که طبق یک قانون یا توافقنامه قرار است انجام دهید',array['obey','adhere to']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"So far the ceasefire has been observed by both sides.","translation":"تاکنون آتش بس از سوی دو طرف رعایت شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257398.mp3"}]'::jsonb,1),
('7f3de866-a09d-5926-b996-b2cbaab32236','ff9cf72e-efb6-5a47-a64b-d918678877a4',5,null,null,'spoken & written','to do things and obey laws that are part of a religion or custom','[ transitive ]',null,'انجام کارها و اطاعت از قوانینی که بخشی از یک دین یا عرف است',array['follow']::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('084f5b89-21b4-531e-90bf-24f505e898ba','6eb2fa8f-5f23-5020-bee1-c1c9965ce1d3',1,null,null,'spoken & written','easy to notice or understand',null,null,'بدیهی، آشکار؛ مشهود (خطا)','{}'::text[],'{}'::text[],array['seem/appear obvious It seems obvious to me that he is guilty.','sound obvious This may sound obvious, but don’t forget to put your name on your paper.','become obvious It soon became obvious that the boy was not really interested.','an obvious reason The plan, for obvious reasons, was being kept secret.','an obvious example This case is an obvious example of what can go wrong.','an obvious question The obvious question is: why?','the obvious answer There is no obvious answer to their problem.','glaringly/blindingly obvious (= extremely obvious ) The cause of her problems is glaringly obvious.','transparently/patently/blatantly obvious (= clearly obvious ) His interest in her was blatantly obvious.','painfully obvious (= very obvious, and embarrassing or upsetting ) It became painfully obvious that she and Edward had nothing in common.','immediately obvious The cause of the pain was not immediately obvious.','fairly/quite obvious ( also pretty obvious spoken ) There are some fairly obvious signs of a poor diet.']::text[],'[{"sentence":"The obvious way of reducing pollution is to use cars less.","translation":"راه واضح کاهش آلودگی استفاده کمتر از خودرو است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001760118.mp3"},{"sentence":"It was obvious that Gina was lying.","translation":"معلوم بود که جینا دروغ می گوید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000257987.mp3"},{"sentence":"It might be obvious to you, but it isn’t to me.","translation":"ممکن است برای شما واضح باشد، اما برای من اینطور نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536177.mp3"}]'::jsonb,3),
('68130ac3-af2d-585c-8e55-2fb89b2ea7bd','6eb2fa8f-5f23-5020-bee1-c1c9965ce1d3',2,null,null,'spoken & written','behaving in a way that shows you want something very badly, when other people think this behaviour is not suitable',null,null,'وقتی دیگران فکر می‌کنند این رفتار مناسب نیست، به گونه‌ای رفتار کنید که نشان دهد شما به شدت چیزی را می‌خواهید','{}'::text[],'{}'::text[],array['seem/appear obvious It seems obvious to me that he is guilty.','sound obvious This may sound obvious, but don’t forget to put your name on your paper.','become obvious It soon became obvious that the boy was not really interested.','an obvious reason The plan, for obvious reasons, was being kept secret.','an obvious example This case is an obvious example of what can go wrong.','an obvious question The obvious question is: why?','the obvious answer There is no obvious answer to their problem.','glaringly/blindingly obvious (= extremely obvious ) The cause of her problems is glaringly obvious.','transparently/patently/blatantly obvious (= clearly obvious ) His interest in her was blatantly obvious.','painfully obvious (= very obvious, and embarrassing or upsetting ) It became painfully obvious that she and Edward had nothing in common.','immediately obvious The cause of the pain was not immediately obvious.','fairly/quite obvious ( also pretty obvious spoken ) There are some fairly obvious signs of a poor diet.']::text[],'[{"sentence":"I know you really like him, but you don’t have to be so obvious about it.","translation":"من می دانم که شما واقعاً او را دوست دارید، اما لازم نیست در مورد آن خیلی واضح باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536184.mp3"}]'::jsonb,1),
('7d86d101-eca0-5390-9d03-59beac7a4594','6eb2fa8f-5f23-5020-bee1-c1c9965ce1d3',3,null,null,'spoken & written',null,null,'the/an obvious choice','بدیهی، آشکار؛ مشهود (خطا)','{}'::text[],'{}'::text[],array['seem/appear obvious It seems obvious to me that he is guilty.','sound obvious This may sound obvious, but don’t forget to put your name on your paper.','become obvious It soon became obvious that the boy was not really interested.','an obvious reason The plan, for obvious reasons, was being kept secret.','an obvious example This case is an obvious example of what can go wrong.','an obvious question The obvious question is: why?','the obvious answer There is no obvious answer to their problem.','glaringly/blindingly obvious (= extremely obvious ) The cause of her problems is glaringly obvious.','transparently/patently/blatantly obvious (= clearly obvious ) His interest in her was blatantly obvious.','painfully obvious (= very obvious, and embarrassing or upsetting ) It became painfully obvious that she and Edward had nothing in common.','immediately obvious The cause of the pain was not immediately obvious.','fairly/quite obvious ( also pretty obvious spoken ) There are some fairly obvious signs of a poor diet.']::text[],'[]'::jsonb,0),
