('d8b360a3-eb60-54ab-b0d0-2f6ebc94b894','8f5691a5-11f5-5891-9277-fa77307b9b32',5,null,null,'spoken & written','a chance for someone to do or say something','[ countable ]',null,'فرصتی برای کسی برای انجام یا گفتن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His question left an opening for me to say exactly what I thought.","translation":"سوال او فرصتی برای من ایجاد کرد تا دقیقاً آنچه را که فکر می کردم بگویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266131.mp3"}]'::jsonb,1),
