('23537a65-a8df-508b-8031-f1e5d4ca7410','e5994c78-6123-5e2a-97c1-4f0e71106546',1,'machine','دستگاه','spoken & written','to use and control a machine or equipment','[ transitive ]',null,'کار کردن (با دستگاه)؛ جراحی کردن؛ بهره‌برداری (شرکت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Lewis family operated a number of boats on the canal.","translation":"خانواده لوئیس تعدادی قایق را در این کانال اداره می کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536353.mp3"},{"sentence":"Clive was experienced in operating the computers.","translation":"کلایو در کار با کامپیوترها تجربه داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266547.mp3"},{"sentence":"Check that the equipment is operating in a safe manner.","translation":"بررسی کنید که تجهیزات به صورت ایمن کار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536359.mp3"},{"sentence":"The bus is designed to operate in all weather conditions.","translation":"این اتوبوس به گونه ای طراحی شده است که در هر شرایط آب و هوایی کار کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536360.mp3"},{"sentence":"Most freezers operate at below –18°C.","translation":"بیشتر فریزرها در دمای زیر 18- درجه سانتیگراد کار می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536361.mp3"}]'::jsonb,5),
('dd39ab81-bc79-50d0-b563-8b57d8a82b6f','e5994c78-6123-5e2a-97c1-4f0e71106546',2,'business/organization','کسب و کار/سازمان','spoken & written','if a business or organization operates in a particular place or way, it works in that place or way','[ intransitive ]',null,'اگر یک کسب و کار یا سازمان در مکان یا روش خاصی فعالیت می کند، در آن مکان یا روش کار می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a design company operating from offices in Seattle","translation":"یک شرکت طراحی که از دفاتری در سیاتل کار می کند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266589.mp3"},{"sentence":"A playgroup operates on the campus.","translation":"یک گروه بازی در محوطه دانشگاه فعالیت می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536364.mp3"},{"sentence":"They were trying to reduce operating costs .","translation":"آنها در تلاش بودند تا هزینه های عملیاتی را کاهش دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536365.mp3"},{"sentence":"Nuns are operating an emergency hospital.","translation":"راهبه ها بیمارستان اورژانسی را اداره می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536366.mp3"}]'::jsonb,4),
('8bd63a50-4bbb-580d-a6a5-8f35140912b8','e5994c78-6123-5e2a-97c1-4f0e71106546',3,'system/process/service','سیستم/فرآیند/سرویس','spoken & written','if a system, process , or service operates, or if you operate it, it works','[ intransitive, transitive ]',null,'اگر سیستم، فرآیند یا سرویسی کار می کند، یا اگر شما آن را اجرا می کنید، کار می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The whole tax system is now operating more efficiently.","translation":"کل سیستم مالیاتی اکنون کارآمدتر عمل می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266566.mp3"},{"sentence":"The new law doesn’t operate in our favour.","translation":"قانون جدید به نفع ما عمل نمی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266567.mp3"},{"sentence":"The car parks operate a pay-as-you-leave system.","translation":"پارکینگ‌ها از سیستم پرداخت مرخصی استفاده می‌کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266572.mp3"},{"sentence":"The bus company operates a Monday to Saturday service.","translation":"شرکت اتوبوس از دوشنبه تا شنبه سرویس دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536369.mp3"}]'::jsonb,4),
('4b9c99ff-1577-5872-a1db-f533a6da62e1','e5994c78-6123-5e2a-97c1-4f0e71106546',4,'medical','پزشکی','spoken & written','to cut into someone’s body in order to repair or remove a part that is damaged','[ intransitive ]',null,'بریدن به بدن کسی به منظور ترمیم یا برداشتن قسمتی که آسیب دیده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Doctors had to operate to remove the bullet.","translation":"پزشکان مجبور شدند برای خارج کردن گلوله عمل کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266578.mp3"},{"sentence":"the surgeon who operated on Taylor’s knee","translation":"جراحي كه زانوي تيلور را جراحي كرد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266581.mp3"}]'::jsonb,2),
('28e01e3d-7e6a-5203-9a9d-cdeeb19272fc','e5994c78-6123-5e2a-97c1-4f0e71106546',5,'work','کار کردن','spoken & written','to do your job or try to achieve things in a particular way','[ intransitive ]',null,'برای انجام کار خود یا تلاش برای رسیدن به اهداف به روشی خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Most people just can’t operate in noisy crowded conditions.","translation":"اکثر مردم نمی توانند در شرایط شلوغ پر سر و صدا کار کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266596.mp3"},{"sentence":"Older children often like to operate independently.","translation":"کودکان بزرگتر اغلب دوست دارند مستقل عمل کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536370.mp3"}]'::jsonb,2),
('9fd20a7e-4392-5882-912e-592ed33e7f0d','e5994c78-6123-5e2a-97c1-4f0e71106546',6,'soldiers/police','سرباز / پلیس','spoken & written','if soldiers or police officers are operating in an area, they are working in that area','[ intransitive ]',null,'اگر سربازان یا افسران پلیس در منطقه ای فعالیت می کنند، در آن منطقه کار می کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Security patrols now operate in some of the most dangerous parts of the city.","translation":"گشت های امنیتی اکنون در برخی از خطرناک ترین نقاط شهر فعالیت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536377.mp3"},{"sentence":"enemy submarines operating in the Mediterranean","translation":"زیردریایی های دشمن در دریای مدیترانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536378.mp3"}]'::jsonb,2),
('dfc9085f-0aee-5f7c-9d0f-dab678e22876','e5994c78-6123-5e2a-97c1-4f0e71106546',7,null,null,'spoken & written',null,null,'operate as something','کار کردن (با دستگاه)؛ جراحی کردن؛ بهره‌برداری (شرکت)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('1381d6dc-5008-51a0-ae01-59f0e6ab87f2','e5994c78-6123-5e2a-97c1-4f0e71106546',8,'laws/principles','قوانین/اصول','spoken & written','to have an effect on something','[ intransitive ]',null,'روی چیزی اثر گذاشتن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the laws of evolution operating on each species","translation":"قوانین تکامل که بر روی هر گونه عمل می کنند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266609.mp3"}]'::jsonb,1),
('79f5d454-f446-5c4f-8924-d4f16e607675','9740ba67-63d9-5d2d-aba5-e5edeb3e5b6a',1,null,null,'spoken & written','your ideas or beliefs about a particular subject','[ countable, uncountable ]','view 1 ( 1 )','نظر، عقیده؛ باور؛ نظر (قانونی)','{}'::text[],'{}'::text[],array['have/hold an opinion Everyone seemed to have a different opinion. He holds strong opinions on these issues.','ask somebody (for) their opinion ( also ask for somebody’s opinion ) We asked people for their opinions about the Olympics. Nobody asked my opinion. It’s a good idea to ask people for their opinions and suggestions.','give/express an opinion (= say what your opinion is ) He gave his opinion only when asked.','voice/state an opinion written (= give your opinion, especially in a formal situation ) She has every right to voice her opinion.','form an opinion (= gradually decide what your opinion is ) Olson had not yet formed an opinion as to Mark’s reliability.','the general opinion (= the opinion that most people have about something ) The general opinion seems to be that the government has made a mess of the war.','popular/public opinion (= what ordinary people think about something ) How much do newspapers influence popular opinion?','somebody’s personal opinion My personal opinion is that his first film was better.','strong opinions People have strong opinions about this subject.','have a difference of opinion (= two people disagree ) He and Luke had a difference of opinion.','something is a matter of opinion (= used to say that you disagree, or that people disagree about something ) ‘He’s a very nice man.’ ‘That’s a matter of opinion, ’ thought Sam.','contrary to popular opinion (= in spite of what most people think ) Contrary to popular opinion, many cats dislike milk.','in my humble opinion (= used when giving your opinion, especially when you want to emphasize what you are about to say ) In my humble opinion, he is the greatest sportsman Britain has produced.','keep your opinions to yourself (= not say what you really think ) As the youngest person there, I knew enough to keep my opinions to myself.','opinion is divided as to/on/over something (= people have different opinions about it ) Opinion was divided as to whether the program will work.','everyone is entitled to their opinion (= used especially when politely disagreeing with what someone says ) Of course everyone is entitled to their opinion, but I can''t accept what he is saying.']::text[],'[{"sentence":"What’s your opinion of Cathy?","translation":"نظر شما در مورد کتی چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266992.mp3"},{"sentence":"He asked his wife’s opinion on every important decision.","translation":"او در مورد هر تصمیم مهمی نظر همسرش را جویا شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266989.mp3"},{"sentence":"The two women had very different opinions about drugs.","translation":"این دو زن نظرات بسیار متفاوتی در مورد مواد مخدر داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266986.mp3"},{"sentence":"In my opinion, the law should be changed.","translation":"به نظر من قانون باید تغییر کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040159.mp3"},{"sentence":"What do you think of Cathy?","translation":"نظر شما در مورد کتی چیست؟","audio_url":null}]'::jsonb,5),
('6a352a98-165f-59c3-a7aa-4aa272f69be8','9740ba67-63d9-5d2d-aba5-e5edeb3e5b6a',2,null,null,'spoken & written','judgment or advice from a professional person about something','[ countable ]',null,'قضاوت یا توصیه یک فرد حرفه ای در مورد چیزی','{}'::text[],'{}'::text[],array['have/hold an opinion Everyone seemed to have a different opinion. He holds strong opinions on these issues.','ask somebody (for) their opinion ( also ask for somebody’s opinion ) We asked people for their opinions about the Olympics. Nobody asked my opinion. It’s a good idea to ask people for their opinions and suggestions.','give/express an opinion (= say what your opinion is ) He gave his opinion only when asked.','voice/state an opinion written (= give your opinion, especially in a formal situation ) She has every right to voice her opinion.','form an opinion (= gradually decide what your opinion is ) Olson had not yet formed an opinion as to Mark’s reliability.','the general opinion (= the opinion that most people have about something ) The general opinion seems to be that the government has made a mess of the war.','popular/public opinion (= what ordinary people think about something ) How much do newspapers influence popular opinion?','somebody’s personal opinion My personal opinion is that his first film was better.','strong opinions People have strong opinions about this subject.','have a difference of opinion (= two people disagree ) He and Luke had a difference of opinion.','something is a matter of opinion (= used to say that you disagree, or that people disagree about something ) ‘He’s a very nice man.’ ‘That’s a matter of opinion, ’ thought Sam.','contrary to popular opinion (= in spite of what most people think ) Contrary to popular opinion, many cats dislike milk.','in my humble opinion (= used when giving your opinion, especially when you want to emphasize what you are about to say ) In my humble opinion, he is the greatest sportsman Britain has produced.','keep your opinions to yourself (= not say what you really think ) As the youngest person there, I knew enough to keep my opinions to myself.','opinion is divided as to/on/over something (= people have different opinions about it ) Opinion was divided as to whether the program will work.','everyone is entitled to their opinion (= used especially when politely disagreeing with what someone says ) Of course everyone is entitled to their opinion, but I can''t accept what he is saying.']::text[],'[{"sentence":"When choosing an insurance policy it’s best to get an independent opinion .","translation":"هنگام انتخاب یک بیمه نامه، بهتر است نظر مستقلی داشته باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267007.mp3"},{"sentence":"My doctor says I need an operation, but I’ve asked for a second opinion (= advice from a second doctor to make sure that the first advice is right ) .","translation":"دکترم می گوید من نیاز به عمل دارم، اما نظر دوم را خواسته ام (=توصیه پزشک دوم برای اطمینان از درست بودن توصیه اول).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000267011.mp3"},{"sentence":"They took the painting to get an expert opinion (= an opinion from someone who knows a lot ) .","translation":"تابلو را گرفتند تا نظر کارشناسی (= نظر کسی که خیلی می داند) بگیرند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001969675.mp3"}]'::jsonb,3),
('a933895d-6a17-57cd-8ce6-96008d8914e3','9740ba67-63d9-5d2d-aba5-e5edeb3e5b6a',3,null,null,'spoken & written',null,null,'have a high/low/good/bad etc opinion of somebody/something','نظر، عقیده؛ باور؛ نظر (قانونی)','{}'::text[],'{}'::text[],array['have/hold an opinion Everyone seemed to have a different opinion. He holds strong opinions on these issues.','ask somebody (for) their opinion ( also ask for somebody’s opinion ) We asked people for their opinions about the Olympics. Nobody asked my opinion. It’s a good idea to ask people for their opinions and suggestions.','give/express an opinion (= say what your opinion is ) He gave his opinion only when asked.','voice/state an opinion written (= give your opinion, especially in a formal situation ) She has every right to voice her opinion.','form an opinion (= gradually decide what your opinion is ) Olson had not yet formed an opinion as to Mark’s reliability.','the general opinion (= the opinion that most people have about something ) The general opinion seems to be that the government has made a mess of the war.','popular/public opinion (= what ordinary people think about something ) How much do newspapers influence popular opinion?','somebody’s personal opinion My personal opinion is that his first film was better.','strong opinions People have strong opinions about this subject.','have a difference of opinion (= two people disagree ) He and Luke had a difference of opinion.','something is a matter of opinion (= used to say that you disagree, or that people disagree about something ) ‘He’s a very nice man.’ ‘That’s a matter of opinion, ’ thought Sam.','contrary to popular opinion (= in spite of what most people think ) Contrary to popular opinion, many cats dislike milk.','in my humble opinion (= used when giving your opinion, especially when you want to emphasize what you are about to say ) In my humble opinion, he is the greatest sportsman Britain has produced.','keep your opinions to yourself (= not say what you really think ) As the youngest person there, I knew enough to keep my opinions to myself.','opinion is divided as to/on/over something (= people have different opinions about it ) Opinion was divided as to whether the program will work.','everyone is entitled to their opinion (= used especially when politely disagreeing with what someone says ) Of course everyone is entitled to their opinion, but I can''t accept what he is saying.']::text[],'[]'::jsonb,0),
('29d02e50-220b-580a-9bc9-1dc2f91bd4e9','9740ba67-63d9-5d2d-aba5-e5edeb3e5b6a',4,null,null,'spoken & written',null,null,'be of the opinion (that)','نظر، عقیده؛ باور؛ نظر (قانونی)','{}'::text[],'{}'::text[],array['have/hold an opinion Everyone seemed to have a different opinion. He holds strong opinions on these issues.','ask somebody (for) their opinion ( also ask for somebody’s opinion ) We asked people for their opinions about the Olympics. Nobody asked my opinion. It’s a good idea to ask people for their opinions and suggestions.','give/express an opinion (= say what your opinion is ) He gave his opinion only when asked.','voice/state an opinion written (= give your opinion, especially in a formal situation ) She has every right to voice her opinion.','form an opinion (= gradually decide what your opinion is ) Olson had not yet formed an opinion as to Mark’s reliability.','the general opinion (= the opinion that most people have about something ) The general opinion seems to be that the government has made a mess of the war.','popular/public opinion (= what ordinary people think about something ) How much do newspapers influence popular opinion?','somebody’s personal opinion My personal opinion is that his first film was better.','strong opinions People have strong opinions about this subject.','have a difference of opinion (= two people disagree ) He and Luke had a difference of opinion.','something is a matter of opinion (= used to say that you disagree, or that people disagree about something ) ‘He’s a very nice man.’ ‘That’s a matter of opinion, ’ thought Sam.','contrary to popular opinion (= in spite of what most people think ) Contrary to popular opinion, many cats dislike milk.','in my humble opinion (= used when giving your opinion, especially when you want to emphasize what you are about to say ) In my humble opinion, he is the greatest sportsman Britain has produced.','keep your opinions to yourself (= not say what you really think ) As the youngest person there, I knew enough to keep my opinions to myself.','opinion is divided as to/on/over something (= people have different opinions about it ) Opinion was divided as to whether the program will work.','everyone is entitled to their opinion (= used especially when politely disagreeing with what someone says ) Of course everyone is entitled to their opinion, but I can''t accept what he is saying.']::text[],'[]'::jsonb,0),
('67cc8f23-70b0-539b-8dbe-a0a73bec0953','eb6881a2-e15f-5dea-8163-46a4190009bd',1,'farming','کشاورزی','spoken & written','relating to farming or gardening methods of growing food without using artificial chemicals , or produced or grown by these methods',null,null,'ارگانیک، طبیعی (پرورش)؛ عضوی (شیمی)','{}'::text[],'{}'::text[],array['organic food/vegetables etc Our restaurant uses only fresh organic vegetables. Many people think that organic food is better for health.','organic farming (= farming without using artificial chemicals ) the environmental benefits of organic farming','organic farmers/farms Organic farmers build up soil fertility by crop rotation. Synthetic fertilisers are banned on organic farms.','organic produce formal (= food produced by organic farming ) The store stocks a wide range of organic produce.','go organic (= buy only organic food, or use only organic methods to farm ) Not all families can afford to go organic.','become organic (= use only organic methods to farm ) More farms are becoming organic, but it is not always an easy choice.','totally/fully organic (= containing only food that is produced using organic methods ) All the ingredients are totally organic.']::text[],'[{"sentence":"Organic farming is better for the environment.","translation":"کشاورزی ارگانیک برای محیط زیست بهتر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269357.mp3"},{"sentence":"organic gardening","translation":"باغبانی ارگانیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713873.mp3"},{"sentence":"The shop sells organic food.","translation":"این فروشگاه غذاهای ارگانیک می فروشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269358.mp3"},{"sentence":"organic wine","translation":"شراب ارگانیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713874.mp3"}]'::jsonb,4),
('97bed0e1-c0e4-5cf6-94c4-32445d727cf7','eb6881a2-e15f-5dea-8163-46a4190009bd',2,'development','توسعه','spoken & written','change or development which is organic happens in a natural way, without anyone planning it or forcing it to happen',null,null,'تغییر یا توسعه ای که ارگانیک است به روشی طبیعی اتفاق می افتد، بدون اینکه کسی آن را برنامه ریزی کند یا مجبور به وقوع آن کند','{}'::text[],'{}'::text[],array['organic food/vegetables etc Our restaurant uses only fresh organic vegetables. Many people think that organic food is better for health.','organic farming (= farming without using artificial chemicals ) the environmental benefits of organic farming','organic farmers/farms Organic farmers build up soil fertility by crop rotation. Synthetic fertilisers are banned on organic farms.','organic produce formal (= food produced by organic farming ) The store stocks a wide range of organic produce.','go organic (= buy only organic food, or use only organic methods to farm ) Not all families can afford to go organic.','become organic (= use only organic methods to farm ) More farms are becoming organic, but it is not always an easy choice.','totally/fully organic (= containing only food that is produced using organic methods ) All the ingredients are totally organic.']::text[],'[{"sentence":"The company’s path to success was by means of organic growth.","translation":"مسیر موفقیت شرکت از طریق رشد ارگانیک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713875.mp3"}]'::jsonb,1),
('425ce7c5-e001-5817-91d6-9788cf3681e6','eb6881a2-e15f-5dea-8163-46a4190009bd',3,'living things','موجودات زنده','spoken & written','living, or produced by or from living things',null,null,'زندگی کردن، یا تولید شده توسط یا از موجودات زنده','{}'::text[],'{}'::text[],array['organic food/vegetables etc Our restaurant uses only fresh organic vegetables. Many people think that organic food is better for health.','organic farming (= farming without using artificial chemicals ) the environmental benefits of organic farming','organic farmers/farms Organic farmers build up soil fertility by crop rotation. Synthetic fertilisers are banned on organic farms.','organic produce formal (= food produced by organic farming ) The store stocks a wide range of organic produce.','go organic (= buy only organic food, or use only organic methods to farm ) Not all families can afford to go organic.','become organic (= use only organic methods to farm ) More farms are becoming organic, but it is not always an easy choice.','totally/fully organic (= containing only food that is produced using organic methods ) All the ingredients are totally organic.']::text[],'[{"sentence":"Adding organic matter such as manure can improve the soil.","translation":"افزودن مواد آلی مانند کود دامی می تواند خاک را بهبود بخشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269331.mp3"},{"sentence":"Bacteria act on organic waste .","translation":"باکتری ها روی زباله های آلی اثر می گذارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713879.mp3"}]'::jsonb,2),
('fa0bbfbb-6d1b-507d-aaba-31ac1717bcfe','eb6881a2-e15f-5dea-8163-46a4190009bd',4,'part of something','بخشی از چیزی','spoken & written','an organic system or relationship is one in which the parts or people fit well and in a comfortable way with each other',null,null,'یک سیستم یا رابطه ارگانیک سیستمی است که در آن اجزا یا افراد به خوبی و به روشی راحت با یکدیگر تناسب داشته باشند','{}'::text[],'{}'::text[],array['organic food/vegetables etc Our restaurant uses only fresh organic vegetables. Many people think that organic food is better for health.','organic farming (= farming without using artificial chemicals ) the environmental benefits of organic farming','organic farmers/farms Organic farmers build up soil fertility by crop rotation. Synthetic fertilisers are banned on organic farms.','organic produce formal (= food produced by organic farming ) The store stocks a wide range of organic produce.','go organic (= buy only organic food, or use only organic methods to farm ) Not all families can afford to go organic.','become organic (= use only organic methods to farm ) More farms are becoming organic, but it is not always an easy choice.','totally/fully organic (= containing only food that is produced using organic methods ) All the ingredients are totally organic.']::text[],'[{"sentence":"an organic relationship between the individual and his community","translation":"یک رابطه ارگانیک بین فرد و جامعه اش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269348.mp3"},{"sentence":"They believe in the organic unity of the universe.","translation":"آنها به وحدت ارگانیک جهان اعتقاد دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001713883.mp3"}]'::jsonb,2),
('4cfd7005-f74d-53dc-939b-09868759f1eb','eb6881a2-e15f-5dea-8163-46a4190009bd',5,'body organs','اندام های بدن','spoken & written','relating to the organs of the body',null,null,'مربوط به اندام های بدن','{}'::text[],'{}'::text[],array['organic food/vegetables etc Our restaurant uses only fresh organic vegetables. Many people think that organic food is better for health.','organic farming (= farming without using artificial chemicals ) the environmental benefits of organic farming','organic farmers/farms Organic farmers build up soil fertility by crop rotation. Synthetic fertilisers are banned on organic farms.','organic produce formal (= food produced by organic farming ) The store stocks a wide range of organic produce.','go organic (= buy only organic food, or use only organic methods to farm ) Not all families can afford to go organic.','become organic (= use only organic methods to farm ) More farms are becoming organic, but it is not always an easy choice.','totally/fully organic (= containing only food that is produced using organic methods ) All the ingredients are totally organic.']::text[],'[{"sentence":"organic diseases","translation":"بیماری های ارگانیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000269341.mp3"}]'::jsonb,1),
('fe510098-bf35-5c11-a990-17feca96905f','bc65521d-347c-5669-8fc5-286775150474',1,null,null,'spoken & written','the final result of a meeting, discussion , war etc – used especially when no one knows what it will be until it actually happens',null,null,'نتیجه، پیامد (نهایی)؛ حاصل (مذاکره)',array['result']::text[],'{}'::text[],array['the final/ultimate outcome The final outcome of the investigation is still to be announced. The ultimate outcome of this controversy remains in doubt.','a likely outcome What is the likely outcome of the election?','a possible outcome When you throw a die, there are six possible outcomes.','a successful outcome Hopes for a successful outcome to the war were fading.','a positive outcome (= a good result ) Everyone is hoping for a positive outcome to the talks.','a happy outcome (= a good result, especially one that makes everyone happy ) Adopting a child does not automatically result in a happy outcome.','a satisfactory outcome Our main aim is to achieve a satisfactory outcome for both parties.','the desired outcome The desired outcome of most services is a satisfied customer.','a favourable/unfavourable outcome Considerable progress has been made towards a favourable outcome. Discontinuing treatment too early may result in an unfavourable outcome.','a learning outcome (= what someone is supposed to learn from something ) It is important to set teaching objectives and learning outcomes.','a policy outcome (= what happens when a particular policy is used ) A number of factors affect policy outcomes.','a treatment outcome (= what happens whan a particular medical treatment is used ) Funding is provided to collect and analyze data on treatment outcomes.','a health outcome (= how healthy someone is after using a particular treatment, system etc ) the assessment of health outcomes','have an outcome The meeting had a very satisfactory outcome.','affect/influence the outcome Did coverage in the media affect the outcome of the trial?','decide/determine the outcome (= be the thing that causes the final result ) This move ultimately decided the outcome of the conflict. At the leadership elections today, it is their votes that will determine the outcome.','predict the outcome (= say what the final result will be ) It is too early to predict the final outcome of the survey.','await the outcome (= wait for the final result ) Medical science must await the outcome of proper international debate.']::text[],'[{"sentence":"It was impossible to predict the outcome of the election.","translation":"پیش بینی نتیجه انتخابات غیرممکن بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000382127.mp3"},{"sentence":"People who had heard the evidence at the trial were surprised at the outcome.","translation":"افرادی که در دادگاه شواهد را شنیده بودند از نتیجه آن شگفت زده شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001558224.mp3"},{"sentence":"It was impossible to predict what would happen in the election.","translation":"پیش بینی اینکه در انتخابات چه اتفاقی خواهد افتاد غیرممکن بود.","audio_url":null}]'::jsonb,3),
('d82b9823-820d-57ca-bc48-d236feeb4cce','51d4697b-d701-5e1c-aa41-aadf37fd46e1',1,null,null,'spoken & written','not inside a building',null,null,'بیرون، در بیرونِ (مکان)',array['outdoors']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"When we got up, it was still dark outside.","translation":"وقتی بلند شدیم بیرون هنوز هوا تاریک بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841372.mp3"},{"sentence":"Go and play outside.","translation":"برو بیرون بازی کن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841373.mp3"},{"sentence":"Could you wait outside please.","translation":"میشه لطفا بیرون منتظر بمونی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841375.mp3"},{"sentence":"I’ll meet you outside the theatre at two o''clock.","translation":"ساعت دو بیرون از تئاتر با شما ملاقات خواهم کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020151.mp3"},{"sentence":"Several people were standing in the hallway outside of his room.","translation":"چند نفر در راهرو بیرون اتاقش ایستاده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841378.mp3"},{"sentence":"We went outside to see what was happening.","translation":"رفتیم بیرون ببینیم چه خبره.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841381.mp3"},{"sentence":"I opened the door and looked outside.","translation":"در را باز کردم و بیرون را نگاه کردم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841382.mp3"}]'::jsonb,7),
('bb131e3d-f865-5f50-9776-a257488f6728','51d4697b-d701-5e1c-aa41-aadf37fd46e1',2,null,null,'spoken & written','not in a particular city , country etc',null,null,'نه در یک شهر، کشور و غیره خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She often travels outside the UK.","translation":"او اغلب به خارج از بریتانیا سفر می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000383475.mp3"},{"sentence":"We camped a few miles outside the town.","translation":"چند مایلی خارج از شهر کمپ زدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841386.mp3"},{"sentence":"Bolton is a mill town just outside Manchester.","translation":"بولتون یک شهر آسیاب در خارج از منچستر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000383478.mp3"},{"sentence":"Maritza, 19, lives in Everett, outside of Boston.","translation":"ماریتزا، 19 ساله، در اورت، خارج از بوستون زندگی می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841389.mp3"}]'::jsonb,4),
('49d94b8d-793f-5744-9db5-95d67523a917','51d4697b-d701-5e1c-aa41-aadf37fd46e1',3,null,null,'spoken & written','beyond the limits or range of a situation, activity etc',null,null,'فراتر از محدوده یا محدوده یک موقعیت، فعالیت و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s outside my experience, I’m afraid.","translation":"این خارج از تجربه من است، می ترسم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000383482.mp3"},{"sentence":"children born outside of marriage","translation":"فرزندانی که خارج از ازدواج به دنیا می آیند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841392.mp3"}]'::jsonb,2),
('2496801b-307b-5668-8eb9-25136ad212cd','51d4697b-d701-5e1c-aa41-aadf37fd46e1',4,null,null,'spoken & written','if someone is outside a group of people, an organization etc, they do not belong to it',null,null,'اگر کسی خارج از یک گروه از افراد، یک سازمان و غیره باشد، به آن تعلق ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Few people outside the government realized what was happening.","translation":"تعداد کمی از افراد خارج از دولت متوجه شدند که چه اتفاقی در حال رخ دادن است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841393.mp3"},{"sentence":"The university administrators ignored criticism from outside.","translation":"مدیران دانشگاه انتقادات بیرونی را نادیده گرفتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001841396.mp3"},{"sentence":"Management consultants were brought in from outside the company.","translation":"مشاوران مدیریت از خارج از شرکت وارد شدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000383496.mp3"}]'::jsonb,3),
('a6567754-9d70-5cca-85b4-ca92bd862d5a','51d4697b-d701-5e1c-aa41-aadf37fd46e1',5,null,null,'spoken & written',null,null,'outside of somebody/something','بیرون، در بیرونِ (مکان)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('4283f601-8c04-5c5b-90d2-83683c91b3d2','51d4697b-d701-5e1c-aa41-aadf37fd46e1',6,null,null,'spoken & written','if the time that someone takes to do something, especially finish a race , is outside a particular time, it is greater than that time',null,null,'اگر زمانی که شخصی برای انجام کاری، به ویژه پایان مسابقه، خارج از زمان خاصی باشد، بیشتر از آن زمان است.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He finished in 10 minutes 22.4 seconds, 4 seconds outside the record.","translation":"او در 10 دقیقه و 22.4 ثانیه، 4 ثانیه خارج از رکورد به پایان رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001982708.mp3"}]'::jsonb,1),
('e2668cd7-3ed2-577d-bc25-6d8f3d44e963','8aaca258-2ee1-5f81-a639-7fec0e353d71',1,null,null,'spoken & written','not inside a building',null,null,'بیرونی، خارجی (ساختمان)؛ حاشیه‌ای (شهر)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We turned off the outside lights and went to bed.","translation":"چراغ های بیرون را خاموش کردیم و به رختخواب رفتیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000383592.mp3"},{"sentence":"The house will need a lot of outside repairs before we can sell it.","translation":"خانه قبل از اینکه بتوانیم آن را بفروشیم به تعمیرات بیرونی زیادی نیاز دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000383593.mp3"}]'::jsonb,2),
